var PUZZLES_MORE = [
  {"id":"o-driver","title":"深夜的代驾","tag":"推理系","cats":["悬疑","推理","反转"],"original":true,"difficulty":2,"par":8,"surface":"男人叫了代驾回家。到家后，他给了代驾一笔远超车费的小费，还特意叮嘱：“明天要是有人问起，就说你今晚十一点就把我送到了。”第二天，男人被警方带走。为什么？","truth":"男人当晚在一场酒局上与人起了冲突，之后对方死于非命。他需要一个不在场证明，于是雇代驾替自己作伪证。可代驾因为收了异常高的小费起了疑，回家查了新闻，主动报了警。他叮嘱的“十一点送到”，恰好把自己从案发时间里摘了出去——也正是这句话，让警方锁定了他的嫌疑。","truthKeywords":["代驾","小费","不在场证明","作伪证","案发时间","十一点","酒局","口角","冲突","报警","警方"],"coreKeywords":["代驾","不在场证明","作伪证"],"hints":["那笔小费不是慷慨，而是一份价码。","他真正想要的，不是回家，而是有人替他记住一个时间。","他叮嘱的那句话，最后成了指向他自己的证据。"],"clues":[{"kw":["代驾","叫车","司机"],"type":"yes","text":"是。送他回家的那个人，不是普通出租车司机。"},{"kw":["小费","多给钱","给钱多"],"type":"yes","text":"是。他多给了一笔钱——但那不是慷慨。"},{"kw":["不在场证明","不在场","证明"],"type":"yes","text":"是。他要的不是回家，而是有人替他证明一个时间。"},{"kw":["案发时间","十一点","时间点"],"type":"yes","text":"是。他叮嘱的那个时间，正是全案最关键的一刻。"},{"kw":["撒谎","说谎"],"type":"partial","text":"部分正确。确实有一句谎话，但说这句话的人后来反悔了。"},{"kw":["认识死者","仇人","仇杀"],"type":"no","text":"不是。他和死者算不上仇人，只是一场酒局上的口角。"},{"kw":["车祸","酒驾","撞人"],"type":"no","text":"不是。他喝了酒，但没有开车——这正是他叫代驾的原因。"},{"kw":["报警","自首","被抓"],"type":"yes","text":"是。最后是他自己雇来的那个人，把他送进了警局。"},{"type":"irr","kw":["男人叫了"],"text":"与此无关。「男人叫了」不在这个故事里，换个方向问吧。"}]},
  {"id":"o-floor13","title":"电梯没有十三层","tag":"微恐系","cats":["恐怖","微恐","都市传说"],"original":true,"difficulty":2,"par":8,"surface":"写字楼电梯的按钮面板上，12 的上面直接就是 14，没有 13 层。保安却坚称这栋楼有 13 层，而且每晚都有人上去。为什么？","truth":"13 层是机房和档案室，为了避讳没有挂牌。每晚上去的人是保安自己——他要到 13 层巡更打卡。可打卡记录里，每晚都有两次记录：一次是他的，另一次属于三年前在 13 层加班时猝死、却始终没被从考勤系统里删掉的员工。保安不敢声张，只能一遍遍地说“这栋楼有 13 层”。","truthKeywords":["13层","机房","档案室","避讳","保安","巡更","打卡","考勤系统","猝死","加班","记录","没删"],"coreKeywords":["13层","打卡","考勤系统"],"hints":["不挂牌，是出于一个很旧的讲究。","每晚上去的人，其实就站在这栋楼的一楼。","真正的破绽，在打卡记录里多出来的那一行。"],"clues":[{"kw":["机房","档案室","设备间","仓库"],"type":"yes","text":"是。13 层不是给人办公的，它属于另一类房间。"},{"kw":["避讳","忌讳","不吉利","数字"],"type":"yes","text":"是。不挂牌，是出于一个很旧的讲究。"},{"kw":["保安","巡更","值班","巡查"],"type":"yes","text":"是。每晚上去的人，是这栋楼的保安自己。"},{"kw":["打卡","考勤","签到"],"type":"yes","text":"是。全案的突破口，藏在打卡记录里。"},{"kw":["猝死","加班死","过世","死了"],"type":"yes","text":"是。记录里的另一个人，早就死了。"},{"kw":["闹鬼","鬼魂","灵异","阴魂"],"type":"no","text":"不是。楼上没有鬼——只有一个没被系统删掉的名字。"},{"kw":["13层","十三层","没有13"],"type":"yes","text":"是。13 层确实存在——只是它不在按钮面板上。"},{"kw":["两次记录","多出来一行","两个人的记录"],"type":"partial","text":"部分正确。记录里每晚都有两次打卡——一次是他的，另一次没人敢解释。"},{"type":"irr","kw":["写字楼电"],"text":"与此无关。汤主摇头：「写字楼电」和汤底扯不上。"}]},
  {"id":"o-lamp","title":"那盏灯没有亮","tag":"推理系","cats":["悬疑","推理","都市"],"original":true,"difficulty":1,"par":6,"surface":"他从未和对面楼那户人家说过一句话。可某个晚上，他发现那扇窗的灯第一次没有亮，立刻拿起电话报了警。为什么？","truth":"对面住着一位独居老人。两栋楼离得很近，两人每晚都会隔着窗看见对方那盏灯，谁也没说过话，却默认这是彼此“还平安”的信号。灯没亮，说明老人出事了。警察破门进去，发现老人已经摔倒在地上两天。","truthKeywords":["对面楼","独居老人","老人","灯","窗户","信号","报平安","摔倒","破门","警察","从没说过话","邻居"],"coreKeywords":["灯","独居老人","报平安"],"hints":["那盏灯不是用来照明的。","两户人从没说过话，却有一个谁都没说破的约定。"],"clues":[{"kw":["老人","独居","一个人住"],"type":"yes","text":"是。那扇窗后面，住着一位独居的老人。"},{"kw":["窗户","那盏灯"],"type":"yes","text":"是。灯不是照明用的——它是两个人之间唯一的约定。"},{"kw":["信号","约定","默契"],"type":"yes","text":"是。谁也没说过话，却都懂那盏灯的意思。"},{"kw":["摔倒","生病","晕倒","受伤"],"type":"yes","text":"是。那天晚上，老人已经动不了了。"},{"kw":["破门","闯进去","踹门"],"type":"yes","text":"是。警察最后是撞开门进去的。"},{"kw":["认识","朋友","亲戚","家人"],"type":"no","text":"不是。他们从未说过一句话。"},{"kw":["报警","打电话","报110"],"type":"yes","text":"是。灯没亮的那一晚，他做的第一件事是报警。"},{"kw":["对面楼","两栋楼","隔着窗"],"type":"yes","text":"是。两栋楼离得很近，近到能看见彼此窗口的那盏灯。"},{"type":"irr","kw":["他从未和"],"text":"与此无关。这一锅和「他从未和」没有关系，汤主把话题拨了回来。"}]},
  {"id":"o-goodnight","title":"删不掉的晚安","tag":"微恐系","cats":["恐怖","微恐","家庭"],"original":true,"difficulty":2,"par":8,"surface":"女孩整理去世母亲留下的旧手机，在相册里发现一段视频：画面里是她自己熟睡的样子，拍摄时间却是母亲去世后的第三天。她看完之后没有害怕，抱着手机哭了整整一夜。为什么？","truth":"那段视频是母亲生前提前录好的。母亲知道自己时日不多，把一段自己录下的画面交给了手机的定时任务，让它在自己走后第三天自动保存进相册。视频里母亲轻声说：“别怕黑，我再陪你睡一晚。”女孩哭，是因为那是母亲留给她的最后一句晚安。","truthKeywords":["定时","提前录","生前","遗言","遗物","母亲","相册","自动保存","最后一句","晚安","陪伴","去世"],"coreKeywords":["定时","生前","母亲"],"hints":["拍摄时间没错，但录像的人没错过任何事。","她早就知道自己会走，所以提前安排好了一件事。","那不是灵异，是一场精心准备的告别。"],"clues":[{"kw":["提前录","生前录","早就录好","定时"],"type":"yes","text":"是。那段视频，是在她还活着的时候录下的。"},{"kw":["母亲","妈妈"],"type":"yes","text":"是。留下这段影像的人，已经不在了。"},{"kw":["相册","手机","自动保存","定时发送"],"type":"yes","text":"是。有一样东西，在她走后替她完成了这个动作。"},{"kw":["遗言","遗物","最后的话","留言"],"type":"yes","text":"是。那段影像，是她留给女儿的最后几句话。"},{"kw":["晚安","别怕黑","陪你睡"],"type":"yes","text":"是。母亲在视频里，说的是一句很普通的晚安。"},{"kw":["闹鬼","鬼魂","灵异","阴魂","附身"],"type":"no","text":"不是。这不是灵异——这是一个人提前准备好的告别。"},{"kw":["第三天","去世后三天","走后第三天"],"type":"yes","text":"是。视频的拍摄时间是她走后的第三天——可录像的人早就安排好了一切。"},{"kw":["抱着手机","舍不得"],"type":"partial","text":"部分正确。她哭不是因为害怕，而是因为听懂了一句话。"},{"type":"irr","kw":["女孩整理"],"text":"与此无关。「女孩整理」不在这个故事里，换个方向问吧。"}]},
  {"id":"o-badge","title":"医院里的全勤通知","tag":"悬疑系","cats":["悬疑","职场","反转"],"original":true,"difficulty":3,"par":9,"surface":"男人在医院昏迷了整整一周。醒来后，他打开手机，发现这一周每天都收到了公司的全勤打卡通知。他看完，立刻向公司递交了辞呈。为什么？","truth":"昏迷前，他把工牌和门禁卡借给了一位急需用钱的同事，让对方替他打卡应付考勤。可那位同事不只是打卡——他还模仿他的签名，签下了一份他完全不知情的担保文件，并用他的身份领走了工资。全勤通知说明，那个人还在继续使用他的身份。他辞职，是为了彻底切断这条被冒用的身份链。","truthKeywords":["工牌","门禁卡","借给","同事","打卡","全勤","签名","模仿","担保文件","冒用身份","工资","辞职"],"coreKeywords":["工牌","冒用身份","签名"],"hints":["他昏迷的这段时间，“他”却一直在上班。","这件事的起点，是他主动把一样东西交了出去。","除了打卡，那个人还替他做了别的事。","最后一条：把「工牌」和「冒用身份」连起来想想——它们之间差了什么？"],"clues":[{"kw":["工牌","门禁卡","借给别人","借给同事"],"type":"yes","text":"是。他把能证明“他是他”的东西，交给了别人。"},{"kw":["同事","熟人","身边人"],"type":"yes","text":"是。拿走那些东西的，是他身边的人。"},{"kw":["打卡","考勤","全勤"],"type":"yes","text":"是。那一周有人替他完成了考勤——但做得太多了。"},{"kw":["签名","模仿笔迹","签字"],"type":"yes","text":"是。除了打卡，还有人替他签了字。"},{"kw":["担保","文件","合同","债务"],"type":"yes","text":"是。有一份他完全不知道的文件，用他的名字签了下来。"},{"kw":["黑客","盗号","诈骗集团","外人"],"type":"no","text":"不是。动他身份的不是外人，是他亲手交出去的那双手。"},{"kw":["昏迷","住院","醒过来"],"type":"yes","text":"是。那一周他一直躺在医院里——“他”却在照常上班。"},{"kw":["辞职","递交辞呈","不干了"],"type":"yes","text":"是。他看完那串通知，做的第一件事是辞职。"},{"type":"irr","kw":["男人在医"],"text":"与此无关。汤主摇头：「男人在医」和汤底扯不上。"}]},
  {"id":"o-archive","title":"档案上的同一个生日","tag":"催泪系","cats":["温情","家庭","反转"],"original":true,"difficulty":2,"par":8,"surface":"她在孤儿院长大，十八岁那年拿到了自己的档案。看到出生日期后，她决定去寻找一个从未见过的人。为什么？","truth":"档案上的出生日期，与孤儿院里另一位已故孩子完全相同，连出生医院都一样——她们是同一天在同一家医院出生的双胞胎，其中一个被遗弃在门口。她要去寻找的，是那个孩子的亲生母亲，也就是她自己的母亲。","truthKeywords":["档案","出生日期","同一天","同一家医院","双胞胎","遗弃","孤儿院","已故","母亲","寻找","十八岁"],"coreKeywords":["双胞胎","出生日期","母亲"],"hints":["那个日期，在孤儿院里不是唯一的。","她找到的不是一条线索，而是另一个“自己”。","她要找的人，从来没有抱过她一次。"],"clues":[{"kw":["双胞胎","孪生","同一个生日"],"type":"yes","text":"是。档案里的那个日期，属于两个人。"},{"kw":["出生日期","生日","同一天出生"],"type":"yes","text":"是。那个日期，和别人重复了。"},{"kw":["孤儿院","福利院","院长"],"type":"yes","text":"是。她长大的地方，还留着另一个孩子的记录。"},{"kw":["遗弃","丢弃","丢下","抛弃"],"type":"yes","text":"是。当年有人做了一个决定，把其中一个留在了门口。"},{"kw":["母亲","妈妈","亲生"],"type":"yes","text":"是。她要找的人，从未抱过她一次。"},{"kw":["仇人","凶手","报复","寻仇"],"type":"no","text":"不是。她去找人，不是为了算账。"},{"kw":["十八岁","成年","拿到档案"],"type":"yes","text":"是。她是在十八岁那年拿到档案的——成年那天，她才知道自己是谁。"},{"kw":["同一家医院","医院出生","同一间"],"type":"partial","text":"部分正确。连出生医院都一样——那不是巧合，是同一个源头。"},{"type":"irr","kw":["她在孤儿"],"text":"与此无关。这一锅和「她在孤儿」没有关系，汤主把话题拨了回来。"}]},
  {"id":"o-umbrella","title":"雨天多带的那把伞","tag":"催泪系","cats":["温情","悬疑","都市"],"original":true,"difficulty":2,"par":8,"surface":"每逢下雨，男人的包里都会多带一把伞。同事都笑他多此一举。直到有一天，他没能用上那把伞，却因此救下了一条命。为什么？","truth":"那把伞从来不是给他自己准备的。三年前，他的妻子在雨天等公交时，被一辆因视线不清而失控的车撞倒身亡。从那以后，每逢下雨他都会多带一把伞，递给在雨里等车的人。那天，他把伞给了一位站在站台外侧的孕妇，孕妇因此退回了站台内侧——一辆失控的车随即撞上了她原本站立的位置。那把多余的伞，救下了一条命。","truthKeywords":["伞","妻子","雨天","等公交","失控的车","车祸","三年前","孕妇","站台","递过去","视线不清","救下"],"coreKeywords":["伞","妻子","车祸"],"hints":["那把伞从来不是给自己用的。","这件事的起点，是一个雨天的公交站。","他救人的方式，是让一个人挪开几步。"],"clues":[{"kw":["多带一把","递伞"],"type":"yes","text":"是。他带的东西，从来不是给自己用的。"},{"kw":["妻子","老婆","爱人"],"type":"yes","text":"是。这一切的开始，和他最爱的人有关。"},{"kw":["车祸","失控的车","事故"],"type":"yes","text":"是。三年前的那个雨天，发生过一场事故。"},{"kw":["等公交","站台","候车"],"type":"yes","text":"是。事故发生在一个人等车的时候。"},{"kw":["孕妇","大肚子","怀孩子"],"type":"yes","text":"是。那天他递伞的对象，是一位怀着孩子的女人。"},{"kw":["习惯","强迫症","迷信","讲究"],"type":"no","text":"不是。这不是习惯，而是一个没能放下的人。"},{"kw":["雨天","下雨","下雨天"],"type":"yes","text":"是。只有下雨的日子，他的包里才会多出那一把伞。"},{"kw":["救下","挪开","让开"],"type":"yes","text":"是。他让一个人挪开了几步——几步之外，就是生与死的距离。"},{"type":"irr","kw":["雨男人的"],"text":"与此无关。「雨男人的」不在这个故事里，换个方向问吧。"}]},
  {"id":"o-lift4","title":"停在四楼的电梯","tag":"微恐系","cats":["恐怖","微恐","医院"],"original":true,"difficulty":1,"par":6,"surface":"值夜班的护士每晚十二点都会坐电梯从八楼到一楼。某天，她按了“1”，电梯却先停在了四楼。门开了，外面没有人。她没有害怕，反而立刻按下了紧急呼叫。为什么？","truth":"四楼是手术室。电梯会停，说明有人按了四楼的按钮却没有进来——要么按了就走，要么就倒在门口挡住了门。她按紧急呼叫，是因为她意识到四楼有人需要帮助。保安赶到时，发现一位病人家属晕倒在四楼电梯口。","truthKeywords":["四楼","手术室","紧急呼叫","电梯","按钮","晕倒","病人家属","保安","夜班","护士"],"coreKeywords":["四楼","手术室","晕倒"],"hints":["四楼不是病房，是另一种房间。","门开了却没有人，有两种可能。"],"clues":[{"kw":["手术室","手术层","开刀"],"type":"yes","text":"是。那个楼层不是病房，是另一种房间。"},{"kw":["紧急呼叫","呼叫按钮","求救铃"],"type":"yes","text":"是。她做的第一件事，是叫人。"},{"kw":["晕倒","昏过去","躺在地上"],"type":"yes","text":"是。那天晚上，真的有人躺在门外。"},{"kw":["病人家属","家属","陪床"],"type":"yes","text":"是。倒下的人不是病人，是来陪病人的那位。"},{"kw":["挡住门","感应","按了没进"],"type":"yes","text":"是。电梯会停，是因为门那边有东西挡住了感应。"},{"kw":["闹鬼","鬼魂","灵异","阴魂"],"type":"no","text":"不是。门外没有人站着——但有一个人躺着。"},{"kw":["护士","值夜班","夜班"],"type":"yes","text":"是。她值的是夜班——所以她比谁都清楚四楼意味着什么。"},{"kw":["八楼","一楼","按了1"],"type":"partial","text":"部分正确。她按的是“1”，电梯却先停在了四楼——因为门那边有人按过。"},{"type":"irr","kw":["士每晚十"],"text":"与此无关。汤主摇头：「士每晚十」和汤底扯不上。"}]},
  {"id":"o-mark","title":"画框背面的暗记","tag":"推理系","cats":["悬疑","推理","反转"],"original":true,"difficulty":3,"par":9,"surface":"画廊里，鉴定师对着一幅新送来的画看了三分钟，随后报了警。画本身是真迹，画家也早已去世。问题出在画框背面的一个小记号上。为什么？","truth":"那个暗记是他十年前亲手做的。当年他受命修复一幅名画，在画布背面留下了只有自己认得的编号。后来那幅画在他工作室里失窃，同一天夜里，他的助手离奇死亡，案子至今未破。如今这幅“新送来”的画带着他亲手做的记号出现在画廊，说明当年那场失窃，从来不是意外。","truthKeywords":["暗记","记号","编号","画框背面","修复","失窃","助手","死亡","十年前","鉴定师","名画","悬案"],"coreKeywords":["暗记","失窃","助手"],"hints":["决定性的东西，小到几乎看不见。","那个记号，是鉴定师自己留下的。","画出现过一次“消失”，那次还带走了一个人。","最后一条：把「暗记」和「失窃」连起来想想——它们之间差了什么？"],"clues":[{"kw":["记号","编号","暗记","标记"],"type":"yes","text":"是。决定性的东西，小到几乎看不见。"},{"kw":["画框背面","画布背面","背面"],"type":"yes","text":"是。那个记号，藏在画的背面。"},{"kw":["十年前","当年","很久以前"],"type":"yes","text":"是。这个记号，是很久以前留下的。"},{"kw":["修复","修画","修补"],"type":"yes","text":"是。他当年亲手碰过这幅画——在另一个场合。"},{"kw":["失窃","被偷","盗窃"],"type":"yes","text":"是。这幅画曾经消失过一次。"},{"kw":["助手","学徒","徒弟"],"type":"yes","text":"是。画消失的那天，还有一个人也消失了。"},{"kw":["赝品","假画","仿制","造假"],"type":"no","text":"不是。画是真的——正因为是真的，才可怕。"},{"kw":["报警","报案","叫警察"],"type":"yes","text":"是。他看清那个记号之后，第一反应是报警。"},{"type":"irr","kw":["画廊里鉴"],"text":"与此无关。这一锅和「画廊里鉴」没有关系，汤主把话题拨了回来。"}]},
  {"id":"o-bus","title":"提前一站下车","tag":"推理系","cats":["悬疑","推理","反转"],"original":true,"difficulty":2,"par":8,"surface":"女孩每天都坐末班公交回家。某天，她在终点前一站就下了车，独自走回去。第二天新闻播出那班车出了事故，她一点也不惊讶——因为三天前她就已经知道会出事。为什么？","truth":"三天前，她在车上捡到一本司机遗落的笔记本。本子里记着同一条线路每一次刹车异常的时刻和应对方式——那是司机在给自己做心理准备：他知道这辆车的刹车迟早会彻底失灵，却不敢上报，怕丢掉工作。她算出了笔记上标注的日期，也去报了警，可没有人相信。所以那天她提前下车，是跑着去求救的。","truthKeywords":["笔记本","司机","刹车","失灵","笔记","日期","报警","没人信","提前下车","线路","心理准备"],"coreKeywords":["笔记本","刹车","失灵"],"hints":["三天前，她在车上捡到了一样东西。","写那些字的人，就坐在驾驶座上。","她不是预言家——她只是提前读到了答案。"],"clues":[{"kw":["笔记本","本子","笔记"],"type":"yes","text":"是。三天前，她在车上捡到了一样东西。"},{"kw":["司机","驾驶员","开车的人"],"type":"yes","text":"是。写那些字的人，就坐在驾驶座上。"},{"kw":["刹车","制动","刹不住"],"type":"yes","text":"是。那辆车最致命的地方，从来不在发动机上。"},{"kw":["失灵","故障","坏掉"],"type":"yes","text":"是。有人早就知道，这辆车迟早会出问题。"},{"kw":["报警","报案","求救","没人信"],"type":"yes","text":"是。她试过求救，但没有被相信。"},{"kw":["诅咒","预言","预感","灵异"],"type":"no","text":"不是。她不是预言家——她只是读了一本本子。"},{"kw":["末班车","公交","每天坐"],"type":"yes","text":"是。她每天都坐那班末班车回家——直到那天提前一站下了车。"},{"kw":["三天前","提前知道","早就知道"],"type":"yes","text":"是。她三天前就知道了——答案写在一本别人遗落的笔记里。"},{"type":"irr","kw":["女孩每天"],"text":"与此无关。「女孩每天」不在这个故事里，换个方向问吧。"}]},
  {"id":"medschool","title":"解剖课","tag":"经典谜题","cats":["恐怖","惊悚","校园"],"difficulty":3,"par":9,"surface":"医学院的三名学生 A、B、C 是同宿舍的室友。A 成绩优异，是班长；B 身体一直很虚弱。某天清晨，有人在解剖教室里发现了 A 和 B 的尸体，而 C 彻底疯了。这一夜究竟发生了什么？","truth":"当晚 A 的梦游症发作。他在梦游中走进解剖教室，把因低血糖昏倒、躺在解剖台上的 B，当成了教学用的尸体，开始按课堂上学过的步骤进行解剖。B 在剧痛中死去。C 半夜去找两人，推开门看见了那一幕——A 满手是血地站在被剖开的 B 身旁，还在梦游。C 当场精神崩溃。","truthKeywords":["梦游","梦游症","解剖","解剖台","解剖教室","尸体","当成","低血糖","昏倒","班长","室友","疯了"],"coreKeywords":["梦游","解剖","尸体"],"hints":["那一夜，有人在睡着的时候做了一件极其清醒的事。","B 倒下的原因，和他的体质直接相关。","A 一直以为自己只是在完成一门功课。","最后一条：把「梦游」和「解剖」连起来想想——它们之间差了什么？"],"clues":[{"kw":["梦游","梦游症","睡梦中行动"],"type":"yes","text":"是。A 有一种会在夜里发作的病——他自己完全不知道。"},{"kw":["解剖","解剖课","解剖教室"],"type":"yes","text":"是。那间教室里正在上的，是一门关于人体的课。"},{"kw":["低血糖","晕倒","昏过去"],"type":"yes","text":"是。B 在那一夜先失去了意识。"},{"kw":["当成尸体","误认","认错"],"type":"yes","text":"是。A 把躺着的 B，认成了另一样东西。"},{"kw":["疯了","精神崩溃","失常"],"type":"yes","text":"是。C 推开门的那一刻，看见了不该看见的东西。"},{"kw":["谋杀","他杀","仇杀","报复"],"type":"no","text":"不是。没有人怀着恨意动手。"},{"kw":["自杀","轻生"],"type":"no","text":"不是。这不是任何人的选择。"},{"kw":["疾病","身体","虚弱"],"type":"partial","text":"部分正确。B 的体质确实是伏笔，但直接死因不是它。"},{"type":"irr","kw":["医学院的"],"text":"与此无关。汤主摇头：「医学院的」和汤底扯不上。"}]},
  {"id":"seat","title":"婚礼上的空座位","tag":"悬疑系","cats":["温情","催泪","家庭"],"difficulty":3,"par":9,"surface":"婚礼上，新娘在头桌留了一个空座位，摆上一副碗筷。敬酒时她对着空位说：“妈，我嫁人了。”宾客都知道，新娘的母亲半年前去世了。轮到新郎的父亲来敬酒，新娘的目光落在他手腕上——那里戴着一串她再熟悉不过的佛珠。她忽然站起，把那个空座位上的碗筷收了回去。为什么？","truth":"那串佛珠是母亲下葬时的陪葬品，本不该出现在世上。新娘看见它戴在公公手腕上，才明白半年前母亲墓地那次“整理”究竟意味着什么——墓被盗过，而盗墓的人，正是新郎的父亲。她收起了给母亲的碗筷，因为这场婚礼已经不可能继续。","truthKeywords":["佛珠","陪葬","随葬","墓地","被盗","盗墓","公公","新郎的父亲","空座位","母亲","去世","碗筷"],"coreKeywords":["佛珠","盗墓","陪葬"],"hints":["那个空位不是摆设，它属于一位已经不在的人。","让新娘变脸的东西很小，小到可以戴在手腕上。","那件东西本该永远埋在地下。","最后一条：把「佛珠」和「盗墓」连起来想想——它们之间差了什么？"],"clues":[{"kw":["母亲","妈妈","去世"],"type":"yes","text":"是。那个空位，是留给一位已经不在的人。"},{"kw":["空座位","空位","留座"],"type":"yes","text":"是。那个位置，是她特意空出来的。"},{"kw":["佛珠","手串","念珠"],"type":"yes","text":"是。改变一切的东西，是一串珠子。"},{"kw":["陪葬","随葬","下葬"],"type":"yes","text":"是。那串珠子，本该和某个人一起埋在地下。"},{"kw":["盗墓","墓地"],"type":"yes","text":"是。半年前，有人动过那座墓。"},{"kw":["公公","新郎的父亲","新郎爸爸"],"type":"yes","text":"是。戴上它的人，正是新郎的父亲。"},{"kw":["忘记","疏忽","搞错"],"type":"no","text":"不是。这不是谁的一时疏忽。"},{"kw":["彩礼","家产"],"type":"irr","text":"与此无关。这件事和钱没有关系。"}]},
  {"id":"umbrellanight","title":"门口的黑伞","tag":"微恐系","cats":["恐怖","微恐","都市传说"],"difficulty":3,"par":9,"surface":"深夜大雨，独居的男人听见敲门声，开门却没有人，门口只放着一把湿透的黑伞。他把伞收好放在玄关。第二天，邻居告诉他：昨夜楼下有个人被车撞死了，手里还攥着另一把一模一样的伞。为什么？","truth":"敲门的是他的女友。两人当晚争吵，女友摔门冲进雨里。几分钟后她后悔了，折返敲门想回来。男人正在气头上，故意没有立刻开门。女友等了十几秒，转身走向马路想拦车离开，被一辆雨夜中视线不清的货车撞死——那是一场车祸。门口那把黑伞，是她等门时留下的；她手里攥着的，是另一把。","truthKeywords":["女友","吵架","争吵","摔门","折返","回来","敲门","故意","没开门","马路","货车","车祸","撞死","黑伞"],"coreKeywords":["女友","敲门","车祸"],"hints":["敲门的人和他关系很近，而且刚刚才离开。","她在门口等了十几秒，然后走向了一个危险的地方。","那两把伞本来是一对。","最后一条：把「女友」和「敲门」连起来想想——它们之间差了什么？"],"clues":[{"kw":["女友","女朋友","爱人"],"type":"yes","text":"是。敲门的人，和他关系很近。"},{"kw":["吵架","争吵","闹别扭"],"type":"yes","text":"是。那晚他们刚刚吵过一架。"},{"kw":["折返","回来","反悔"],"type":"yes","text":"是。她走了之后，又回过头来。"},{"kw":["没开门","故意","赌气"],"type":"yes","text":"是。他听见了敲门声，却没有立刻开门。"},{"kw":["马路","街上","拦车"],"type":"yes","text":"是。她最后走向了一个很危险的地方。"},{"kw":["车祸","货车","撞死"],"type":"yes","text":"是。夺走她生命的，是雨夜里一辆看不清路的车。"},{"kw":["凶手","谋杀","仇人"],"type":"no","text":"不是。没有人想害她——包括他自己。"},{"kw":["灵异","闹鬼"],"type":"irr","text":"与此无关。门口没有鬼，只有一把伞。"}]},
  {"id":"nolight","title":"不许开灯的房间","tag":"推理系","cats":["恐怖","微恐","怪谈"],"difficulty":2,"par":8,"surface":"女孩租下一间很便宜的老房子。房东反复叮嘱她：晚上无论听见什么，都不要开灯。她住了三个月都照做了。第四个月的某个晚上，她第一次打开了灯，然后连夜搬走了。为什么？","truth":"房东不许她开灯，是因为这间老房子的线路早就严重老化。深夜电压不稳，一旦开灯，老化的线路就会过热起火——上一任租客正是因此葬身火海。女孩那晚开灯后闻到了焦糊味、看见插座冒出火星，才明白那句叮嘱的真正含义：房东怕的不是她看见什么，而是房子烧起来。","truthKeywords":["电路","线路","老化","短路","起火","火灾","前任租客","烧死","焦糊味","插座","火星","房东","开灯"],"coreKeywords":["线路","起火","开灯"],"hints":["房东的叮嘱和“看见什么”无关。","这栋房子的某个系统，已经老得不能再用了。","她开灯那一刻，闻到了不该有的味道。"],"clues":[{"kw":["电路","线路","电线"],"type":"yes","text":"是。这栋房子的某个系统，已经老得不能再用了。"},{"kw":["老化","年久失修","太旧"],"type":"yes","text":"是。它一直在等待一个时机。"},{"kw":["起火","火灾","烧起来"],"type":"yes","text":"是。房东真正怕的，是火。"},{"kw":["前任租客","以前的租客","上一个住的人"],"type":"yes","text":"是。在她之前，这里住过别人——那个人没能走出去。"},{"kw":["焦糊味","糊味","插座","火星"],"type":"yes","text":"是。她开灯那一刻，闻到了不该有的味道。"},{"kw":["灵异","闹鬼","阴魂"],"type":"no","text":"不是。房间里没有鬼。"},{"kw":["谋杀","凶手","害她"],"type":"no","text":"不是。房东不是想害她，恰恰相反。"},{"kw":["危险","不安全","有问题"],"type":"partial","text":"部分正确。确实有危险，但危险来自一个很现实的地方。"},{"type":"irr","kw":["女孩租下"],"text":"与此无关。这一锅和「女孩租下」没有关系，汤主把话题拨了回来。"}]},
  {"id":"autoreply","title":"删不掉的回复","tag":"悬疑系","cats":["恐怖","微恐","都市传说"],"difficulty":3,"par":9,"surface":"男孩每天给去世的女友发消息，从没收到回复。某天深夜，他收到了一条回复：“别再发了。”他愣了很久，然后报了警。为什么？","truth":"女友半年前遇害身亡，凶手至今没有落网，她的手机也一直下落不明。男孩收到的这条回复里，有一个他从未见过的错别字习惯——而凶手在案发现场留下的字条上，犯过一模一样的错。他因此确认：拿着她手机的人，就是那个凶手。","truthKeywords":["女友","去世","遇害","凶手","手机","回复","错别字","字条","案发现场","冒用","报警"],"coreKeywords":["凶手","手机","错别字"],"hints":["回消息的人，已经不在了。","那句话的写法，暴露了一个人的身份。","警方在现场见过同样的破绽。","最后一条：把「凶手」和「手机」连起来想想——它们之间差了什么？"],"clues":[{"kw":["去世","死了","遇害","不在人世"],"type":"yes","text":"是。给他回消息的人，已经不在人世。"},{"kw":["凶手","杀人犯","作案的人"],"type":"yes","text":"是。拿着那部手机的人，就是害她的人。"},{"kw":["手机","遗物","下落不明"],"type":"yes","text":"是。她的手机，从案发那天起就不见了。"},{"kw":["错别字","习惯","用词","语气"],"type":"yes","text":"是。那句话的写法，暴露了另一个人的身份。"},{"kw":["字条","现场","证据"],"type":"yes","text":"是。警方在现场发现过一样东西，上面有同样的破绽。"},{"kw":["复活","没死","还活着"],"type":"no","text":"不是。她确实已经死了，这一点没有转机。"},{"kw":["恶作剧","玩笑","黑客"],"type":"no","text":"不是。这不是玩笑，也不是随便哪个陌生人。"},{"kw":["托梦","灵异"],"type":"irr","text":"与此无关。这条消息是活人发出来的。"}]},
  {"id":"bathtub","title":"楼上漏水","tag":"推理系","cats":["悬疑","推理","家庭"],"difficulty":3,"par":9,"surface":"男人发现自家天花板开始渗水，于是上楼敲门。楼上住户不在家，门缝里却一直在往外渗水。他叫来物业打开门，屋里空无一人，浴缸的水龙头却开着，水已经漫过了地板。他当场报警。为什么？","truth":"浴缸里泡着一具尸体。凶手一直开着水龙头，是为了加快尸体腐烂、扰乱死亡时间的判断，同时把现场伪装成水管爆裂。屋里空无一人、水却漫过地板，正说明这不是意外，而是有人特意布置出来的现场。","truthKeywords":["浴缸","尸体","泡水","凶手","腐烂","死亡时间","死因","假象","拖延","现场","报警"],"coreKeywords":["尸体","浴缸","死亡时间"],"hints":["那间屋子并不是空的。","水龙头开着，不是为了淹死谁。","有人在骗法医的时间判断。","最后一条：把「尸体」和「浴缸」连起来想想——它们之间差了什么？"],"clues":[{"kw":["浴缸","浴盆"],"type":"yes","text":"是。水是从一件家具里漫出来的。"},{"kw":["尸体","死人","遗体"],"type":"yes","text":"是。那间屋子里其实不是空的。"},{"kw":["腐烂","腐坏","泡着"],"type":"yes","text":"是。放水不是为了淹死谁，而是为了掩盖别的什么。"},{"kw":["死亡时间","死亡原因","死因"],"type":"yes","text":"是。有人想骗过法医的时间判断。"},{"kw":["凶手","布置","伪造"],"type":"yes","text":"是。这个现场，是被人特意摆出来的。"},{"kw":["水管爆裂","漏水","意外"],"type":"no","text":"不是。水管好得很——这不是意外。"},{"kw":["自杀","轻生"],"type":"no","text":"不是。没有人是自己躺进去的。"},{"kw":["出差","旅游","不在家"],"type":"irr","text":"与此无关。屋主在不在家，不是重点。"}]},
  {"id":"lasttrain","title":"最后一班地铁","tag":"悬疑系","cats":["悬疑","推理","旅途"],"difficulty":2,"par":8,"surface":"女孩加班到深夜，赶上了最后一班地铁。车厢里只有她和一个看起来睡着的老人。到站后她下车，回头却看见老人仍在熟睡——而这是这趟车的终点站。她跑回站台值班室求救。为什么？","truth":"车厢里那位老人并没有睡着——他已经没有了呼吸。而那一站是终点站，列车到站后会被开进车辆段检修，没有人会清点车厢。女孩意识到，如果她不管，这位老人会被连同列车一起遗忘在车库里。她跑去站台值班室求救，是为了让人尽快找到他。","truthKeywords":["老人","睡着","没有呼吸","死亡","终点站","车辆段","检修","列车员","清车"],"coreKeywords":["老人","没有呼吸","终点站"],"hints":["车厢里那位老人，不是在睡觉。","那趟车到站之后，会被开进一个没人清点乘客的地方。","她跑去找人，是为了让老人被尽快找到。"],"clues":[{"kw":["老人","老年人","老爷爷"],"type":"yes","text":"是。车厢里还有一位上了年纪的人。"},{"kw":["睡着","睡觉","打盹"],"type":"yes","text":"是。他看起来像是在睡觉。"},{"kw":["没有呼吸","断气","停止呼吸"],"type":"yes","text":"是。他不是在睡——他已经停止了呼吸。"},{"kw":["终点站","最后一站","终点"],"type":"yes","text":"是。那是这趟车能到的最后一站。"},{"kw":["车辆段","检修","回车库"],"type":"yes","text":"是。到了那里，列车会被开进一个没人清点乘客的地方。"},{"kw":["谋杀","凶手","被害"],"type":"no","text":"不是。没有人对他动手。"},{"kw":["闹鬼","灵异","鬼魂"],"type":"no","text":"不是。他是一位真正的乘客。"},{"kw":["坐过站","睡过头","迷路"],"type":"irr","text":"与此无关。这不是坐过站的问题。"}]},
  {"id":"dogquiet","title":"邻居家的狗","tag":"推理系","cats":["悬疑","推理","都市"],"difficulty":2,"par":8,"surface":"女人独自住在郊区。每天傍晚，邻居家的狗都会隔着篱笆朝她叫。某天傍晚，狗一声都没叫，她却立刻锁门报警。为什么？","truth":"那条狗对任何陌生人都狂吠不止，唯独对熟人一声不吭。邻居一家当天正在外地旅行，院子里不该有任何人。狗不叫，说明有一个熟人进了邻居家的院子——而她还看见，邻居家的窗户里亮起了灯。她立刻明白：有人拿着钥匙，趁主人不在进了屋。","truthKeywords":["狗","不叫","熟人","陌生人","邻居","旅行","不在家","院子","灯","入室","钥匙","报警"],"coreKeywords":["狗","不叫","熟人"],"hints":["那条狗只对一种人保持安静。","邻居一家当天并不在家。","她还看见了另一件不该发生的事。"],"clues":[{"kw":["宠物","看门狗"],"type":"yes","text":"是。那声没响起来的叫声，来自一条狗。"},{"kw":["不叫","没叫","安静"],"type":"yes","text":"是。它那天反常地安静。"},{"kw":["熟人","认识的人","认识他"],"type":"yes","text":"是。它不叫，是因为它认识进来的人。"},{"kw":["邻居","隔壁","对门"],"type":"yes","text":"是。出事的是住在旁边的那户人家。"},{"kw":["旅行","不在家","出门"],"type":"yes","text":"是。那户人家当天不该有人。"},{"kw":["亮灯","窗户"],"type":"yes","text":"是。她看见了另一件不该发生的事。"},{"kw":["狗生病","狗死了","中毒"],"type":"no","text":"不是。那条狗没事。"},{"kw":["野兽","动物"],"type":"irr","text":"与此无关。郊区没有野兽。"}]},
  {"id":"sparekey","title":"多出来的钥匙","tag":"悬疑系","cats":["恐怖","微恐","家庭"],"difficulty":2,"par":8,"surface":"男人搬进新租的房子，房东交给他一把钥匙，说这是唯一的钥匙。可某天下班回家，他发现门是开着的，屋里一切如常，只是鞋柜上多了一把钥匙。他拿起那把钥匙，脸色惨白。为什么？","truth":"那把钥匙能打开他的门，说明房东撒了谎——“唯一的钥匙”不止一把。而多出来的那把，是上一个租客留下的。上一个租客并不是搬走的：他在这间屋子里失踪了，案子至今未结。男人意识到，有人一直留着这把钥匙，可以随时进来。","truthKeywords":["钥匙","房东","撒谎","唯一","上一个租客","失踪","案子","留下","随时进来","门开着"],"coreKeywords":["钥匙","上一个租客","失踪"],"hints":["那把钥匙不是谁的疏忽，它属于另一个人。","房东那句“唯一”，是假的。","住在他之前的那个人，从来没有搬走。"],"clues":[{"kw":["钥匙","第二把","多了一把"],"type":"yes","text":"是。多出来的那件东西，本来只该有一把。"},{"kw":["房东","中介","房主"],"type":"yes","text":"是。交给他钥匙的人，说了谎。"},{"kw":["撒谎","说谎","不止一把"],"type":"yes","text":"是。那句“唯一”是假的。"},{"kw":["上一个租客","以前的租客","前租客"],"type":"yes","text":"是。这把钥匙属于住在他之前的人。"},{"kw":["失踪","不见","消失"],"type":"yes","text":"是。那个人没有搬走——他消失了。"},{"kw":["案子","警察","调查","悬案"],"type":"yes","text":"是。这件事至今没有结案。"},{"kw":["小偷","撬锁","盗窃"],"type":"no","text":"不是。门没有被撬过。"},{"kw":["搬家公司","忘带","遗漏"],"type":"irr","text":"与此无关。这把钥匙不是谁忘下的。"}]},
  {"id":"dreamself","title":"楼下的自己","tag":"微恐系","cats":["恐怖","惊悚","反转"],"difficulty":3,"par":9,"surface":"心理医生连续三周接待同一位病人。病人每次都讲述同一个梦：他站在一栋楼的天台上，看着楼下的自己。第四周，病人没有来。医生打开新闻，看到一则坠楼报道，立刻认出了死者。为什么？","truth":"病人患的是多重人格障碍，他梦里的“楼下的自己”，是另一重人格。第四周他没有来，是因为另一重人格占据了主导，并选择了坠楼。医生认出死者，是因为报道里的地址和时间，与病人反复描述的那个梦完全吻合——他一直梦见的，是自己的死亡。","truthKeywords":["解离","多重人格","人格","梦","天台","楼下","坠楼","新闻","死者","地址","死亡"],"coreKeywords":["多重人格","坠楼","梦"],"hints":["他的身体里，住着不止一个人。","他梦见的那个“自己”，也是他。","医生是从一条消息里认出他的。","最后一条：把「多重人格」和「坠楼」连起来想想——它们之间差了什么？"],"clues":[{"kw":["多重人格","人格分裂","解离","分裂"],"type":"yes","text":"是。他的身体里，住着不止一个人。"},{"kw":["做梦","梦境"],"type":"yes","text":"是。他反复讲的那个梦，是关键。"},{"kw":["天台","楼顶","屋顶"],"type":"yes","text":"是。梦里的地点，是一栋楼的最高处。"},{"kw":["楼下","下面","另一个自己"],"type":"yes","text":"是。他在梦里看见的那个人，也是他自己。"},{"kw":["坠楼","跳楼","摔下"],"type":"yes","text":"是。他梦见的结局，是一种坠落。"},{"kw":["新闻","报道","报纸"],"type":"yes","text":"是。医生是从一条消息里认出他的。"},{"kw":["预言","预知","超能力"],"type":"no","text":"不是。他没有预言能力——那只是他自己的病。"},{"kw":["谋杀","凶手","推他"],"type":"no","text":"不是。没有人推他。"},{"type":"irr","kw":["心理医生"],"text":"与此无关。「心理医生」不在这个故事里，换个方向问吧。"}]},
  {"id":"nightcamera","title":"会移动的相框","tag":"微恐系","cats":["恐怖","微恐","都市传说"],"difficulty":2,"par":8,"surface":"女孩搬进新家后，总觉得家具的位置被人动过：椅子会转向门口，相框会倒扣在桌上。她装了摄像头。第二天她看完录像，收拾行李离开了。为什么？","truth":"录像里，她养的那只猫每天凌晨会跳上椅子，把相框推倒。但真正让她崩溃的，是画面里另一个身影——她自己。她每晚都在梦游，坐在椅子上，面向门口一动不动。她怕的不是家具被移动，而是录像里那个她自己都不认识的人。","truthKeywords":["摄像头","录像","梦游","自己","猫","相框","椅子","凌晨","门口","害怕"],"coreKeywords":["梦游","录像","自己"],"hints":["动家具的“人”，一直住在这间屋子里。","录像里出现了一只小动物。","她怕的不是家具，而是画面里的另一个人。"],"clues":[{"kw":["梦游","睡梦中","无意识"],"type":"yes","text":"是。录像里那个动家具的人，是她自己。"},{"kw":["摄像头","监控","录像"],"type":"yes","text":"是。让她看清真相的，是一段影像。"},{"kw":["宠物"],"type":"yes","text":"是。录像里还有一只小动物。"},{"kw":["相框","照片","椅子"],"type":"yes","text":"是。被挪动的东西，都是很普通的家具。"},{"kw":["凌晨","半夜","夜里"],"type":"yes","text":"是。那些事都发生在同一个时间段。"},{"kw":["闹鬼","灵异","鬼魂","小偷"],"type":"no","text":"不是。屋里没有别人，也没有鬼。"},{"kw":["恶作剧","整人","朋友"],"type":"no","text":"不是。没有人跟她开这种玩笑。"},{"kw":["生病","身体","不正常"],"type":"partial","text":"部分正确。确实和她的身体有关，但不是外伤。"},{"type":"irr","kw":["女孩搬进"],"text":"与此无关。汤主摇头：「女孩搬进」和汤底扯不上。"}]},
  {"id":"samecase","title":"同款行李箱","tag":"推理系","cats":["推理","旅途","反转"],"difficulty":2,"par":8,"surface":"机场行李转盘上，男人一眼认出自己的行李箱——不是因为牌子，而是因为箱子侧面那道只有他知道的划痕。可当他拎起箱子，却发现重量不对。他没有打开，而是直接报了警。为什么？","truth":"那道划痕是他自己做的记号，箱子却重得不正常，说明里面的东西已经被调包了。他不敢打开，是因为他清楚：如果有人故意换掉他的箱子，里面很可能装着违禁品——只要他一开箱，指纹就留在了上面。他报警，是为了把自己从这件事里摘出去。","truthKeywords":["划痕","记号","重量","调包","违禁品","指纹","报警","行李箱","转盘"],"coreKeywords":["调包","违禁品","指纹"],"hints":["他认箱子的依据，是一个只有他自己知道的痕迹。","箱子的手感变了。","他不敢打开，是因为怕留下自己的痕迹。"],"clues":[{"kw":["划痕","记号","标记"],"type":"yes","text":"是。他认箱子的依据，是一个只有他知道的痕迹。"},{"kw":["重量","轻重","手感不对"],"type":"yes","text":"是。箱子的手感变了。"},{"kw":["调包","换了","拿错"],"type":"yes","text":"是。有人动过这只箱子。"},{"kw":["违禁品","走私","毒品","非法"],"type":"yes","text":"是。里面装的东西，是违法的。"},{"kw":["指纹","证据","留下痕迹"],"type":"yes","text":"是。他不敢碰，是因为怕留下自己的痕迹。"},{"kw":["报警","警察"],"type":"yes","text":"是。他做的第一件事，是找人。"},{"kw":["自己的东西","记错","没认错"],"type":"no","text":"不是。箱子不是他记错了——确实被人换过。"},{"kw":["超重","托运","罚款"],"type":"irr","text":"与此无关。和超重费用没有关系。"}]},
  {"id":"bridesmaid","title":"抢话筒的伴娘","tag":"悬疑系","cats":["温情","催泪","家庭"],"difficulty":3,"par":9,"surface":"婚礼上，伴娘忽然冲上台抢过话筒，说这婚不能结。全场哗然。新娘却抱着伴娘哭了。为什么？","truth":"伴娘在新娘的捧花里发现了一枚不属于任何人的药片，又在化妆间听见新郎打电话，提到一份巨额保险的赔付条件。她想起新娘说过，新郎刚给她买了一份以她为受益人的意外险。她冲上台抢过话筒，是为了当着所有人的面拦住这场婚礼——只有把事情闹大，新娘才安全。","truthKeywords":["药片","捧花","保险","意外险","新郎","伴娘","化妆间","电话","拦住","危险"],"coreKeywords":["药片","保险","新郎"],"hints":["她在花束里摸到了一样不该出现的东西。","这件事和一份文件有关。","危险来自最亲近的那个人。","最后一条：把「药片」和「保险」连起来想想——它们之间差了什么？"],"clues":[{"kw":["药片","安眠药"],"type":"yes","text":"是。她在花束里摸到了一样不该出现的东西。"},{"kw":["保险","意外险","保单"],"type":"yes","text":"是。这件事和一份文件有关。"},{"kw":["新郎","未婚夫","男方"],"type":"yes","text":"是。危险来自最亲近的那个人。"},{"kw":["伴娘","闺蜜","好朋友"],"type":"yes","text":"是。冲上台的人，是新娘最信任的朋友。"},{"kw":["化妆间","电话","偷听"],"type":"yes","text":"是。她还听见了一段不该听见的对话。"},{"kw":["前男友","旧情人","吃醋"],"type":"no","text":"不是。这和新娘的感情史无关。"},{"kw":["恶作剧","喝醉","闹场"],"type":"no","text":"不是。她不是来闹事的。"},{"kw":["彩礼","嫁妆","钱多钱少"],"type":"irr","text":"与此无关。这里的关键不是钱多钱少。"}]},
  {"id":"uniform","title":"哥哥的旧校服","tag":"催泪系","cats":["温情","催泪","校园"],"difficulty":1,"par":6,"surface":"弟弟考上大学，母亲翻出一件洗得发白的旧校服给他当行李。弟弟认出那是哥哥的，当场红了眼眶，坚持要穿这件去报到。为什么？","truth":"哥哥五年前为了救落水的弟弟溺水身亡。哥哥生前说过，等他考上大学，要把自己那件校服传给弟弟。弟弟穿着这件洗得发白的旧校服去报到，是为了替哥哥完成那个没能实现的愿望。","truthKeywords":["哥哥","溺水","救他","去世","校服","遗物","考上大学","愿望","弟弟","五年前"],"coreKeywords":["哥哥","溺水","校服"],"hints":["这件衣服原本属于另一个人。","那个人死在水里，而且和弟弟有关。"],"clues":[{"kw":["哥哥","兄长","大哥"],"type":"yes","text":"是。这件衣服原本属于另一个人。"},{"kw":["溺水","淹死","落水"],"type":"yes","text":"是。那个人死在一种很安静的水里。"},{"kw":["救他","为了救","替他"],"type":"yes","text":"是。那个人是为了一件与弟弟有关的事走的。"},{"kw":["去世","死了","不在了"],"type":"yes","text":"是。他已经不在了。"},{"kw":["遗物","留下的","生前"],"type":"yes","text":"是。这件衣服是他留下来的东西。"},{"kw":["愿望","约定","说好"],"type":"yes","text":"是。这件衣服本来承载着一个约定。"},{"kw":["离家出走","失联","失踪"],"type":"no","text":"不是。他不是走丢了。"},{"kw":["学费","家里没钱"],"type":"irr","text":"与此无关。这和家里有没有钱没关系。"}]},
  {"id":"cliffphoto","title":"悬崖上的合影","tag":"悬疑系","cats":["悬疑","推理","旅途"],"difficulty":2,"par":8,"surface":"驴友在山崖边发现一部遗落的手机，相册里最后一张照片是悬崖边五个人的合影。他把照片发到网上寻人，警方看到后却告诉他：照片里这五个人，两年前就已经全部遇难了。为什么？","truth":"这张照片是两年前拍的，手机的主人当年就死在这座山里。两年来，那部手机一直躺在崖边的石缝里，直到最近连日的暴雨把它冲了出来。驴友以为这是“新”的照片，其实它记录的，是两年前那场五人全部遇难的山难。","truthKeywords":["两年前","山难","遇难","暴雨","冲出来","石缝","手机","旧照片","时间","遗体","全部"],"coreKeywords":["两年前","山难","手机"],"hints":["这张照片不属于现在。","那部手机在一个很危险的地方躺了很久。","让它重新出现的原因，是天气。"],"clues":[{"kw":["两年前","以前","很久"],"type":"yes","text":"是。这张照片不属于现在。"},{"kw":["山难","遇难","出事","事故"],"type":"yes","text":"是。五个人都死于同一场灾难。"},{"kw":["暴雨","下雨","冲刷"],"type":"yes","text":"是。让手机重新出现的原因，是天气。"},{"kw":["石缝","崖边","掉在","遗落"],"type":"yes","text":"是。那部手机在一个很危险的地方躺了很久。"},{"kw":["手机","遗物","相册"],"type":"yes","text":"是。拍照的工具，本身就是一件遗物。"},{"kw":["谋杀","凶手","害死"],"type":"no","text":"不是。没有人害他们。"},{"kw":["闹鬼","灵异","鬼魂"],"type":"no","text":"不是。照片里没有鬼。"},{"kw":["寻人","失踪","找人"],"type":"irr","text":"与此无关。没有人需要被寻找——他们早就被找到了。"}]},
  {"id":"seasidebride","title":"海边的新娘","tag":"催泪系","cats":["温情","催泪","旅途"],"difficulty":2,"par":8,"surface":"女人每年都在同一天去同一片海滩，穿同一件婚纱，站到日落才离开。今年她第一次没有去。邻居说，那天她在家睡了一整天。为什么？","truth":"她的未婚夫在婚礼当天为救一个落水的孩子溺亡在这片海里。此后每一年，她都穿着那件婚纱去海边等他——那一天，本该是他们结婚的日子。今年她没有去，是因为她终于把婚纱捐了出去，也终于开始接受心理治疗。她不是忘了，而是决定带着他活下去。","truthKeywords":["未婚夫","溺亡","婚礼","婚纱","海边","同一天","纪念","放下","心理治疗","救孩子"],"coreKeywords":["未婚夫","溺亡","婚纱"],"hints":["她每年纪念的，是一个人。","那个人死在水里，而且本该是她最幸福的那一天。","今年她没去，是因为她做了一个决定。"],"clues":[{"kw":["未婚夫","男朋友","爱人"],"type":"yes","text":"是。她每年纪念的，是一个人。"},{"kw":["溺亡","淹死","溺水"],"type":"yes","text":"是。那个人死在水里。"},{"kw":["婚礼","结婚","婚纱"],"type":"yes","text":"是。那件事发生在本该最幸福的一天。"},{"kw":["海边","海滩","大海"],"type":"yes","text":"是。她每年去的那个地方，离水很近。"},{"kw":["救孩子","救人","为别人"],"type":"yes","text":"是。他是为了另一个人走的。"},{"kw":["放下","走出来了","释怀"],"type":"yes","text":"是。今年不一样了——她终于做了一个决定。"},{"kw":["忘记","不记得","忘了"],"type":"no","text":"不是。她一天都没有忘记。"},{"kw":["搬家","离开城市","换工作"],"type":"irr","text":"与此无关。她一直住在那座城市。"}]},
  {"id":"recorder","title":"会议室里的录音笔","tag":"悬疑系","cats":["悬疑","职场","反转"],"difficulty":2,"par":8,"surface":"清洁工在会议室捡到一支录音笔，随手按下播放键，听见的却是自己的名字。她没有继续听，而是直接交给了主管。三天后，她辞职了。为什么？","truth":"那段录音是管理层开会时留下的，讨论的正是裁员名单，她的名字在第一批。但真正让她决定辞职的，是录音里提到的另一件事：公司打算在她离开之前，把一起安全事故的责任推到她头上。她主动辞职，是为了不让对方有时间操作。","truthKeywords":["录音笔","裁员","名单","名字","安全事故","责任","推给她","辞职","管理层","会议室"],"coreKeywords":["裁员","安全事故","责任"],"hints":["录音里讨论的，是一份名单。","那份名单里有她。","录音里还提到了一件更麻烦的事。"],"clues":[{"kw":["裁员","名单","辞退"],"type":"yes","text":"是。录音里讨论的，是一份名单。"},{"kw":["名字","提到她","被点名"],"type":"yes","text":"是。那份名单里有她。"},{"kw":["安全事故","事故","出事"],"type":"yes","text":"是。录音里还提到了一件更麻烦的事。"},{"kw":["推给她","背锅","栽赃","陷害"],"type":"yes","text":"是。有人打算让她替别人承担后果。"},{"kw":["录音笔","录音","开会"],"type":"yes","text":"是。声音被一支笔留了下来。"},{"kw":["辞职","离开公司"],"type":"yes","text":"是。她做了一个很快的决定。"},{"kw":["升职","加薪","表扬"],"type":"no","text":"不是。这不是一件好事。"},{"kw":["办公室恋情","八卦","绯闻"],"type":"irr","text":"与此无关。录音里没有这种事。"}]},
  {"id":"oldphoto","title":"老照片里的孩子","tag":"推理系","cats":["温情","家庭","反转"],"difficulty":2,"par":8,"surface":"男人在老宅整理遗物时翻出一张黑白照片，照片上是一群孩子在老宅门前合影。他忽然发现，照片角落里的一个孩子，长得和自己一模一样。可这张照片的拍摄年份，比他出生早了整整三十年。为什么？","truth":"照片里那个孩子，是他的父亲。父子俩童年时长得几乎一模一样，连衣服都是同一件——母亲把父亲小时候的旧衣改小了给他穿。而照片的年份并没有错：那确实是他出生前三十年，他的父亲在老宅门前留下的童年。","truthKeywords":["父亲","长得像","童年","老宅","照片","年份","旧衣","一模一样"],"coreKeywords":["父亲","长得像","老宅"],"hints":["照片里那个孩子，是他的长辈。","两个人小时候像得几乎分不出来。","他身上那件衣服，本来不是他的。"],"clues":[{"kw":["父亲","爸爸","老爸"],"type":"yes","text":"是。照片里那个孩子，是他的长辈。"},{"kw":["长得像","相貌","一模一样"],"type":"yes","text":"是。两个人小时候像得几乎分不出来。"},{"kw":["童年","小时候","小的时候"],"type":"yes","text":"是。那是另一个人还是孩子的年代。"},{"kw":["老宅","老房子","祖屋"],"type":"yes","text":"是。照片拍的地方，也是他父辈长大的地方。"},{"kw":["旧衣","衣服","改小"],"type":"yes","text":"是。他身上那件衣服，本来不是他的。"},{"kw":["穿越","时空","重生"],"type":"no","text":"不是。没有发生任何违背常理的事。"},{"kw":["双胞胎","兄弟","哥哥"],"type":"no","text":"不是。照片里只有一个孩子是他家的。"},{"kw":["照相馆","相机","胶卷"],"type":"irr","text":"与此无关。照片本身没有任何问题。"}]},
  {"id":"delivery","title":"没点过的外卖","tag":"悬疑系","cats":["恐怖","微恐","都市传说"],"difficulty":3,"par":9,"surface":"女孩一个人住。连续一周，她每天都会收到一份没点过的外卖，备注写着同一句话：“记得趁热吃。”她报了警。警察看完备注，脸色也变了。为什么？","truth":"那些外卖的备注，用的是她母亲独有的错别字习惯。她母亲十年前失踪，案子至今未结。而这个地址她刚搬来不到一个月，除了中介和房东，没有第二个人知道。能同时掌握这两件事的人，只可能是当年带走她母亲的那个人。","truthKeywords":["外卖","备注","错别字","母亲","失踪","地址","刚搬","房东","中介","当年"],"coreKeywords":["备注","母亲","失踪"],"hints":["真正可怕的不是食物，而是那句话的写法。","那是一个只有某个人才会犯的错。","对方知道一个不该被知道的地方。","最后一条：把「备注」和「母亲」连起来想想——它们之间差了什么？"],"clues":[{"kw":["外卖","送餐","快递"],"type":"yes","text":"是。让她不安的，是一份份送上门的东西。"},{"kw":["备注","留言","那句话"],"type":"yes","text":"是。真正可怕的不是食物，而是那句话的写法。"},{"kw":["错别字","写法","习惯"],"type":"yes","text":"是。那是一个只有某个人才会犯的错。"},{"kw":["母亲","妈妈"],"type":"yes","text":"是。写这句话的人，和她有很深的渊源。"},{"kw":["失踪","消失","不见了"],"type":"yes","text":"是。那个人很久以前就消失了。"},{"kw":["地址","新家","搬家"],"type":"yes","text":"是。对方知道一个不该被知道的地方。"},{"kw":["恶作剧","送错","商家"],"type":"no","text":"不是。这不是送错，也不是玩笑。"},{"kw":["追求者","暗恋","喜欢她"],"type":"irr","text":"与此无关。这不是感情问题。"}]},
  {"id":"alarm","title":"不该响的闹钟","tag":"微恐系","cats":["恐怖","微恐","家庭"],"difficulty":2,"par":8,"surface":"男人被一阵闹钟吵醒，摸黑按掉后翻身继续睡。第二天醒来，他想起那台闹钟的电池早在三个月前就被他自己取出来了。他抓起钥匙就冲了出去，连夜搬走并报了警。为什么？","truth":"那台闹钟三个月前就没电了，电池是他亲手取出来的。它昨晚却响了，还被他摸黑按掉。这说明在他睡着的时候，有人进过房间，装上了电池，并且清楚闹钟的位置。他不敢开灯确认屋里还有没有别人，抓起钥匙就冲了出去，连夜搬走并报了警。","truthKeywords":["闹钟","电池","取出来","响了","进过房间","有人","位置","搬走","报警","睡着"],"coreKeywords":["闹钟","电池","进过房间"],"hints":["吵醒他的那个东西，本不该响。","它缺少一样让它工作的东西，而那样东西是他亲手拿走的。","有人在他睡着的时候来过。"],"clues":[{"kw":["闹钟","定时"],"type":"yes","text":"是。吵醒他的那个东西，本不该响。"},{"kw":["电池","没电","取出来"],"type":"yes","text":"是。它缺少一样让它工作的东西。"},{"kw":["进过房间","有人进来","闯入"],"type":"yes","text":"是。有人在他睡着时来过。"},{"kw":["位置","很熟悉","知道在哪"],"type":"yes","text":"是。那个人对这间屋子很熟。"},{"kw":["搬走","离开","逃跑"],"type":"yes","text":"是。他做的第一件事是离开。"},{"kw":["报警","警察"],"type":"yes","text":"是。他离开之后，找了一个能保护自己的人。"},{"kw":["梦游","幻听","错觉"],"type":"no","text":"不是。那不是他的错觉。"},{"kw":["邻居","楼上","隔壁"],"type":"irr","text":"与此无关。声音不是从别处传来的。"}]},
  {"id":"staircase","title":"第十三级台阶","tag":"悬疑系","cats":["恐怖","微恐","怪谈"],"difficulty":2,"par":8,"surface":"老楼的楼道一共十二级台阶，女人每天上下班都要数一遍。这天夜里她数到第十三级，第二天一早，她没报警，直接搬走了。为什么？","truth":"她其实看不见，数台阶是她判断自己走到哪一层的方式，一级也不会错。那天夜里多出来的第十三级，是有人在她熟睡时站到了她家门外的平台上，脚下垫着东西，一动不动地站了一整夜。她知道那脚步不是邻居的，所以天亮就搬走了。","truthKeywords":["看不见","失明","盲人","数台阶","门外","门口","一整夜","站了一夜","垫脚","砖头","邻居","脚步","搬走","偷窥"],"coreKeywords":["看不见","失明","盲人"],"hints":["她对数字不会数错——那多出来的一级，是真的多出来了。","她辨认世界的方式，和你我不太一样。","有人没有进门，却在她门外站了很久很久。"],"clues":[{"kw":["看不见","失明","盲人"],"type":"yes","text":"是。她数台阶，是因为她看不见，只能靠数字认路。"},{"kw":["台阶数不对","多了一级","十三级","数错了"],"type":"yes","text":"是。台阶的数目确实不对，而她对数字从来不会数错。"},{"kw":["门外","门口","走廊"],"type":"yes","text":"是。那个人没有进屋，一直停留在她的门外。"},{"kw":["有人进来过","闯入","进屋"],"type":"no","text":"不是。没有人进过她的家，门锁也完好。"},{"kw":["邻居","楼上的人","隔壁的人"],"type":"irr","text":"与此无关。邻居的脚步，她听得出来。"},{"kw":["要害她","谋杀","杀她"],"type":"partial","text":"部分正确。那个人确实不怀好意，但那一夜他什么也没来得及做。"},{"kw":["报警","警察"],"type":"no","text":"不是。她没有报警，只是连夜搬走了。"},{"kw":["垫脚","砖头","垫高"],"type":"yes","text":"是。有人把东西垫在了脚下，所以她才会数出多余的那一级。"}]},
  {"id":"postcard","title":"一个「安」字","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":2,"par":8,"surface":"老人每年生日都会收到一张明信片，从同一座城市寄来，落款只有一个“安”字。他从不回信，也不去找。今年生日快过了，信没来，他却笑了。为什么？","truth":"寄明信片的是他失散多年的女儿。当年他不得已把她送给别人抚养，分别时两人约定：只要她平安，每年生日就寄一个“安”字回来。今年信没来，不是她出了事，而是她终于回到了这座城市，不必再靠明信片报平安了。所以他笑了。","truthKeywords":["女儿","孩子","亲人","明信片","卡片","约定","承诺","平安","生日","失散","抚养","回到","报平安","团聚"],"coreKeywords":["女儿","孩子"],"hints":["那些卡片不是随便寄来的，是有人在守一个约定。","一年一封，一个字——那个字里包着的意思是“我还好”。","今年没收到信，对他来说是好事。想想她如今在哪儿。"],"clues":[{"kw":["明信片","卡片"],"type":"yes","text":"是。这些年她一直用一张卡片报信。"},{"kw":["女儿","孩子","亲人"],"type":"yes","text":"是。寄信的人，是他的孩子。"},{"kw":["约定","承诺","说好"],"type":"yes","text":"是。他们之间有一个只有彼此知道的约定。"},{"kw":["平安","过得很好","没事"],"type":"yes","text":"是。只要她过得好，就会寄一个字回来。"},{"kw":["回来了","搬到附近","住在同一座城"],"type":"yes","text":"是。今年她不必再寄信了，因为她已经回到他身边。"},{"kw":["去世","生病","出事"],"type":"no","text":"不是。信停了，不是因为她遭遇了不幸。"},{"kw":["忘记","失忆","不记得"],"type":"no","text":"不是。她从来没有忘记过他。"},{"kw":["恨他","怪他","怨恨"],"type":"irr","text":"与此无关。当年的事，他们谁也不恨谁。"}]},
  {"id":"signal","title":"十分钟里的三个红灯","tag":"推理系","cats":["推理","都市","反转"],"difficulty":1,"par":6,"surface":"出租车司机在十分钟里连闯了三个红灯。交警拦下他，看了一眼后排，只说了一句“跟我走”，还在前面替他开路。为什么？","truth":"出租车的后排躺着一位临产的孕妇，羊水已经破了，正赶着去医院。司机是在抢时间，交警看清车里之后立刻放行，还开着警车替他在前面清道。","truthKeywords":["孕妇","临产","要生了","生孩子","羊水","医院","产房","抢时间","交警","放行","开路","救护"],"coreKeywords":["孕妇","临产","要生了"],"hints":["闯三个红灯，不是为了逃,而是为了抢。","后排坐着一个人，她的状态让交警立刻改了主意。"],"clues":[{"kw":["孕妇","大肚子","要生的女人"],"type":"yes","text":"是。车上载着一位马上要生的孕妇。"},{"kw":["医院","急诊","产房"],"type":"yes","text":"是。他们正赶去医院，一分钟都耽误不起。"},{"kw":["羊水","见红","快生了"],"type":"yes","text":"是。她已经在车上发作了，情况非常紧急。"},{"kw":["交警","警察","拦车"],"type":"yes","text":"是。拦下他的交警，职责就是处理违章。"},{"kw":["开路","帮忙","护送"],"type":"yes","text":"是。交警看清车里之后，反过来替他开道。"},{"kw":["熟人","认识","亲戚"],"type":"no","text":"不是。他们素不相识，交警只是看见了后排的情况。"},{"kw":["罚款","扣分","吊销"],"type":"no","text":"不是。他这一次闯红灯，没有被罚。"},{"kw":["喝酒","醉驾","逃逸"],"type":"irr","text":"与此无关。司机全程清醒，也没有撞到任何人。"}]},
  {"id":"latemeal","title":"凌晨两点的外卖","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":2,"par":8,"surface":"男人独居，每天凌晨两点都会收到一份外卖，备注写着“放门口就好，不要敲门”。他从来没点过，也从来没退过。三个月后的一天，外卖停了，他在门口坐了一整夜。为什么？","truth":"这些订单是他母亲生前设好的定时外卖。她怕儿子熬夜不吃饭，就在手机里预约了整整一年，每天凌晨送到，还特意叮嘱一句：别敲门，别吵醒他。三个月后余额用完，订单停了，他才明白那些饭是谁点的。","truthKeywords":["母亲","妈妈","去世","定时","预约","外卖","熬夜","不吃饭","叮嘱","余额","订单","生前"],"coreKeywords":["母亲","妈妈","去世"],"hints":["这份外卖不是他点的，但确实是为他点的。","点餐的人很早以前就安排好了这一切，一天一天地送。","备注里那句“别敲门”，是怕吵醒谁？"],"clues":[{"kw":["母亲","妈妈","家里人"],"type":"yes","text":"是。点这份外卖的人，是他最亲的家人。"},{"kw":["去世","走了","不在了"],"type":"yes","text":"是。那个人已经不在人世了。"},{"kw":["提前订","定时","预约"],"type":"yes","text":"是。这些订单是很久以前就设好的，会自己一天天送来。"},{"kw":["没吃饭","不吃饭","熬夜"],"type":"yes","text":"是。她最放心不下的，是他半夜不吃饭。"},{"kw":["怕敲门","不想吵醒","备注"],"type":"yes","text":"是。备注只有一句：别敲门——她怕吵醒睡着的儿子。"},{"kw":["恶作剧","开玩笑","骚扰"],"type":"no","text":"不是。没有人拿他开玩笑。"},{"kw":["女友","朋友","同事"],"type":"no","text":"不是。点餐的不是他身边的人。"},{"kw":["余额","钱不够","账户"],"type":"yes","text":"是。三个月后，账户里的钱用完了，订单才停下。"},{"type":"irr","kw":["男人独居"],"text":"与此无关。这一锅和「男人独居」没有关系，汤主把话题拨了回来。"}]},
  {"id":"locksmith","title":"门锁完好","tag":"推理系","cats":["推理","家庭","反转"],"difficulty":2,"par":8,"surface":"老人出门时总要把门反锁三道，回家时门锁完好无损，可抽屉和柜子却被人翻过。他换了一把新锁，情况还是一模一样。为什么？","truth":"翻他东西的人，是房东。房东手里有整套钥匙，也备着备用钥匙，每次进来翻完，都会把门重新锁好，所以老人回家时看不出异样。他换了新锁也没用，房东照样能配出新钥匙。","truthKeywords":["房东","房主","备用钥匙","配钥匙","钥匙","翻东西","抽屉","锁好","换锁","租客"],"coreKeywords":["房东","备用钥匙"],"hints":["门锁没被撬，说明那个人有钥匙。","这个人能随时进出他的家，而且理直气壮。","换锁解决不了问题，因为对方随时能让新锁变成旧的。"],"clues":[{"kw":["房东","房主","收租的人"],"type":"yes","text":"是。能自由进出这间屋子的，是把它租给他的人。"},{"kw":["备用钥匙","配钥匙","另一把钥匙"],"type":"yes","text":"是。对方手里还有一把钥匙，而且随时能再配一把。"},{"kw":["翻抽屉","翻东西","找东西"],"type":"yes","text":"是。那个人进屋不是为了偷大件，而是翻他的抽屉。"},{"kw":["撬锁","砸门","破坏门锁"],"type":"no","text":"不是。门锁从来没被撬过，一点痕迹都没有。"},{"kw":["爬窗","窗户","阳台"],"type":"no","text":"不是。他不是从窗户进来的。"},{"kw":["小偷","盗贼","入室"],"type":"partial","text":"部分正确。那人确实在偷偷翻他的东西，但他不是外人。"},{"kw":["搬家","换房子","搬走"],"type":"irr","text":"与此无关。他没有搬家，一直住在那里。"},{"kw":["监控","摄像头","报警器"],"type":"no","text":"不是。他家里从来没有装过监控之类的东西。"}]},
  {"id":"redumbrella","title":"挂回来的伞","tag":"微恐系","cats":["恐怖","微恐","都市传说"],"difficulty":3,"par":9,"surface":"下雨天，女人在站台把伞借给了一个没带伞的陌生人。第二天早上，那把伞干干净净地挂回了她家门口。她看了一眼，立刻报了警。为什么？","truth":"她借伞时只说过自己住在哪一栋，并没有说过具体的门牌号。第二天伞却挂在了她家门口——那个人在还伞之前，先一路跟着她回了家，记住了她住哪一户。所以她立刻报了警。","truthKeywords":["门牌号","跟着","尾随","跟踪","住哪","家门口","踩点","监视","陌生人","报警"],"coreKeywords":["跟着","尾随","跟踪"],"hints":["伞是怎么找到她家的？她并没有说清楚自己住哪儿。","“还伞”这件事本身，就说明对方知道得太多了。","他先去了哪里，才把伞挂上门的？","最后一条：把「跟着」和「尾随」连起来想想——它们之间差了什么？"],"clues":[{"kw":["门牌号","几楼","哪一户","住哪"],"type":"yes","text":"是。她只说过住哪一栋，从没说过具体是哪一户。"},{"kw":["跟着","尾随","跟踪"],"type":"yes","text":"是。还伞的人在她身后，一路跟到了她家门口。"},{"kw":["门口","门前","家门"],"type":"yes","text":"是。伞是挂在她家门口的，而不是站台的失物处。"},{"kw":["快递","外卖","送错"],"type":"no","text":"不是。那天没有快递，也没有人替她送东西。"},{"kw":["邻居","同楼的人","住户"],"type":"no","text":"不是。那个人她完全不认识，不是同一栋的邻居。"},{"kw":["伞自己回来","灵异"],"type":"irr","text":"与此无关。伞不会自己走路，一切都是有人动手。"},{"kw":["偷东西","进过屋","入室"],"type":"no","text":"不是。她家里没有被翻动过，没有人进去。"},{"kw":["危险","不怀好意","想害她"],"type":"partial","text":"部分正确。那一刻她感到的恐惧是对的，但对方还什么都没做。"},{"kw":["警官","派出所","报警电话"],"type":"yes","text":"是。她当天就把事情交给了警察。"}]},
  {"id":"planeseat","title":"空着的座位","tag":"悬疑系","cats":["悬疑","推理","旅途"],"difficulty":2,"par":8,"surface":"飞机起飞前，空乘发现有一位乘客的座位是空的，可他的行李还放在座位上方的行李架里。广播找了三遍，没人回应。机长随后决定：全体下机。为什么？","truth":"那位乘客办完登机、把行李放上行李架之后，又在起飞前独自离开了飞机。行李还在，人却不见了——这是最危险的信号：无人看管的行李可能被做成爆炸装置。机长按规程请所有人下机，重新安检。","truthKeywords":["行李","登机","离开","下机","清空","重新安检","爆炸","危险物品","无人看管","机长"],"coreKeywords":["行李","重新安检"],"hints":["关键不在人不见了，而在那件东西还留在机上。","他登了机、放下了东西，然后自己走了。","机长宁可全体重来一遍，也不肯赌那件行李是安全的。"],"clues":[{"kw":["行李","背包","箱子"],"type":"yes","text":"是。关键就在那件留在机上的行李。"},{"kw":["下飞机","离开","走出机舱"],"type":"yes","text":"是。那位乘客登了机，又在起飞前自己下了飞机。"},{"kw":["清空","全体下机","重新安检"],"type":"yes","text":"是。机长的做法是把所有人请下来，再从头检查一遍。"},{"kw":["炸弹","危险物品","爆炸"],"type":"partial","text":"部分正确。他们担心的正是那件行李里可能藏着危险的东西。"},{"kw":["晕倒","生病","厕所"],"type":"no","text":"不是。人不在厕所，也没有在机上晕倒。"},{"kw":["迟到","误机","没赶上"],"type":"no","text":"不是。他按时登了机，行李都放好了。"},{"kw":["飞机故障","机械问题"],"type":"irr","text":"与此无关。飞机本身没有任何毛病。"},{"kw":["空乘失职","数错人","点错人数"],"type":"no","text":"不是。人数没有数错，座位确实是空的。"}]},
  {"id":"doorbell","title":"坏掉的门铃","tag":"微恐系","cats":["恐怖","微恐","家庭"],"difficulty":3,"par":9,"surface":"男人独自住在一楼，家里的门铃早就坏了，按不出声。这天深夜他却听见了门铃响，开门一看外面没人。他低头看了看门口的地垫，立刻反锁房门并报了警。为什么？","truth":"他家的门铃坏了，这一点他自己最清楚，所以刚才那声响根本不是门铃——是有人蹲在门外，一边按那个坏铃，一边试着拧他的门锁。地垫上留着一串湿脚印，脚尖朝门、脚跟朝外：那个人是倒退着走开的，因为他在盯着屋里看。","truthKeywords":["门铃坏了","门锁","拧锁","湿脚印","脚印","倒退","蹲","地垫","盯着","反锁","报警"],"coreKeywords":["门铃坏了","门锁"],"hints":["坏了的门铃，是发不出声音的——那刚才是什么在响？","门外的人碰过的东西，不止门铃。","地垫上的痕迹告诉了他：那个人是倒着走的。","最后一条：把「门铃坏了」和「门锁」连起来想想——它们之间差了什么？"],"clues":[{"kw":["门铃坏了","铃不响","按不出声"],"type":"yes","text":"是。他家的门铃确实是坏的，根本按不响。"},{"kw":["门锁","拧锁","撬门"],"type":"yes","text":"是。门外的人碰过他的门锁。"},{"kw":["湿脚印","脚印","地垫"],"type":"yes","text":"是。地垫上留下的痕迹，出卖了那个人的姿势。"},{"kw":["倒退","朝外","反着走"],"type":"yes","text":"是。脚印的方向是反的，说明他是倒着离开的。"},{"kw":["邻居","楼上的人","朋友"],"type":"no","text":"不是。门外的人不是邻居，也不是他认识的人。"},{"kw":["小孩恶作剧","闹着玩","玩笑"],"type":"no","text":"不是。这不是小孩子的恶作剧。"},{"kw":["听错了","幻听","耳鸣"],"type":"no","text":"不是。他没有听错，那声音是真的。"},{"kw":["报了警","警察","报警电话"],"type":"yes","text":"是。他把自己关进屋里之后，第一时间找了警察。"},{"type":"irr","kw":["男人独自"],"text":"与此无关。「男人独自」不在这个故事里，换个方向问吧。"}]},
  {"id":"wardbed","title":"三号床不见了","tag":"微恐系","cats":["恐怖","微恐","医院"],"difficulty":3,"par":9,"surface":"病房里三张床，只住了两个病人。护士每隔半小时查一次房。凌晨三点，她发现靠窗那张床的病人不见了，床单还是热的，输液管还在床边滴着。她立刻按下了报警铃。为什么？","truth":"三号床的病人是全身不能动的重症患者，连翻身都要人帮忙，绝不可能自己下床。床单还热着，输液针头却已经从手上被拔掉，药水滴在地板上——说明有人刚刚进来把他带走了。护士于是立刻按下了报警铃。","truthKeywords":["不能动","瘫痪","重症","输液","针头","床单还热","被带走","搬走","报警","陌生人"],"coreKeywords":["不能动","重症"],"hints":["那个人根本没有能力自己下床。","针头被拔掉了，可人没有被推走。","床单是热的——说明他离开还不到半小时。","最后一条：把「不能动」和「重症」连起来想想——它们之间差了什么？"],"clues":[{"kw":["不能动","瘫痪","动不了"],"type":"yes","text":"是。那位病人几乎不能自己活动，翻身都需要人帮忙。"},{"kw":["重症","病得很重","监护"],"type":"yes","text":"是。他病得很重，一直在输液。"},{"kw":["拔针","针头","输液管"],"type":"yes","text":"是。针头被从手上拔掉了，药水滴到了地板上。"},{"kw":["床单热的","刚离开","还热"],"type":"yes","text":"是。床单还是热的，说明他离开没有多久。"},{"kw":["被带走","被人搬走","推走"],"type":"yes","text":"是。一个动不了的人不会自己消失——是有人把他弄走的。"},{"kw":["自己下床","走去厕所","散步"],"type":"no","text":"不是。他不可能自己下床，更不可能走去厕所。"},{"kw":["转院","换病房","出院"],"type":"no","text":"不是。没有任何转院或出院的记录。"},{"kw":["梦游","睡觉掉下去","滚下床"],"type":"irr","text":"与此无关。这件事和梦游没有关系。"}]},
  {"id":"voicemail","title":"别回来","tag":"微恐系","cats":["恐怖","微恐","家庭"],"difficulty":3,"par":9,"surface":"男人出差在外，深夜给妻子打电话，没人接。半小时后他收到妻子的一条语音留言，只有一句：“别回来。”他听完，立刻打给了邻居。为什么？","truth":"他出门前刚给妻子的手机换电池，正常情况下，没人接听是不会直接跳进语音留言的。而那条留言里没有一点背景声，也没有呼吸声，像是有人拿着手机、照着稿子念出来的。所以他立刻打给邻居，请人去看看妻子还在不在。","truthKeywords":["语音留言","留言","背景声","呼吸声","念稿","换电池","邻居","被控制","绑架","看一看"],"coreKeywords":["语音留言","背景声"],"hints":["妻子不接电话，按常理也不该直接跳进留言。","那段录音安静得不像在一个活人住的屋子里录的。","那句话不像是她自己的语气——像是有人写了、她照着念。","最后一条：把「语音留言」和「背景声」连起来想想——它们之间差了什么？"],"clues":[{"kw":["语音留言","留言","录音"],"type":"yes","text":"是。他收到的不是通话，而是一段留言。"},{"kw":["背景声","呼吸声","太安静"],"type":"yes","text":"是。那段留言安静得反常，一点都不像在家里录的。"},{"kw":["念稿","照着念","背稿"],"type":"yes","text":"是。那句话像是在念给她听的人写的稿子。"},{"kw":["换电池","刚修过","换过电池"],"type":"yes","text":"是。手机的电池是他出门前刚换的，所以不该跳过接听。"},{"kw":["邻居","隔壁的人","楼下的"],"type":"yes","text":"是。他没能立刻赶回去，先找了住得近的人帮忙。"},{"kw":["吵架","生气","闹脾气"],"type":"no","text":"不是。妻子没有生他的气，那句话不是赌气。"},{"kw":["信号不好","没电","关机"],"type":"no","text":"不是。手机没有关机，电量也足够。"},{"kw":["开玩笑","恶作剧","整他"],"type":"no","text":"不是。没有人拿这件事跟他开玩笑。"},{"kw":["被绑","被人挟持","屋里有人"],"type":"partial","text":"部分正确。那一刻她身边很可能有别人，但留言不是她自己想说的。"},{"type":"irr","kw":["男人出差"],"text":"与此无关。汤主摇头：「男人出差」和汤底扯不上。"}]},
  {"id":"o-stamp","title":"多贴的一张邮票","tag":"推理系","cats":["悬疑","推理","反转"],"difficulty":2,"par":8,"original":true,"surface":"男人每个月都给狱中的老友寄一封信。这一次，他特意在信封上多贴了一张邮票。两周后收到回信，他只看了一眼信封，就立刻报了警。为什么？","truth":"他和狱中的老友约好了一个暗号：如果老友平安，回信的信封上就多贴一张邮票；如果邮票没有多，就说明他出事了。这次他寄信时特意多贴一张，是在催老友报平安。可信寄回来，信封上只有一张邮票——他知道这封信不是老友写的，有人冒用他的名字回信，老友很可能已经被胁迫或被害，于是立刻报警。","truthKeywords":["邮票","暗号","信封","回信","狱中","老友","报平安","多贴","出事","报警","胁迫","冒用"],"coreKeywords":["邮票","暗号","冒用"],"hints":["他多贴的那张邮票，不是为了寄得更快。","信封上的邮票数量，是他们之间的一句暗语。","老友没法说话——但信封可以替他说话。"],"clues":[{"kw":["邮票","多贴一张","邮票数量"],"type":"yes","text":"是。邮票的数量本身，就是一句话。"},{"kw":["暗号","约定","暗语"],"type":"yes","text":"是。他们早就约定好了一个只有两个人懂的说法。"},{"kw":["信封","回信","来信"],"type":"yes","text":"是。关键不在信里写了什么，而在信封外面。"},{"kw":["监狱","服刑","坐牢","狱中"],"type":"yes","text":"是。收信的人失去了自由，没法随便说话。"},{"kw":["被胁迫","被控制","冒充"],"type":"yes","text":"是。这封回信不是他本人写的——有人替他写了。"},{"kw":["老友","好友","朋友"],"type":"yes","text":"是。写信和收信的两个人，是过命的交情。"},{"kw":["邮费","涨价","欠邮资","寄错"],"type":"no","text":"不是。多贴邮票不是为了补邮费，信也没有寄错。"},{"kw":["生病","疾病","去世","自杀"],"type":"irr","text":"与此无关。老友不是病死的，也不是自杀。"}]},
  {"id":"o-hallway","title":"走廊尽头的轮椅","tag":"微恐系","cats":["恐怖","微恐","医院"],"difficulty":2,"par":9,"original":true,"surface":"医院的走廊里，有一辆空轮椅。值夜班的护工每晚都会把它推到走廊尽头，再推回原处。这晚她推回来时，觉得轮椅沉了一下。她掀开坐垫，随后推着轮椅直接去了保安室。为什么？","truth":"这几个月病房里总有人丢东西，走廊的监控却什么都没拍到——唯一的盲区就在那辆轮椅的位置。护工发现后，每晚故意把轮椅推来推去，是在等偷东西的人把赃物藏进去。今晚她推回来时觉得沉了一下，掀开坐垫，底下果然塞着一只装满现金和药瓶的布袋。她直接推着轮椅去了保安室。","truthKeywords":["轮椅","坐垫","赃物","偷","监控","走廊","医院","布袋","现金","药瓶","护工","藏","保安室"],"coreKeywords":["轮椅","坐垫","赃物"],"hints":["她每晚推来推去，不是为了锻炼身体。","那辆轮椅有一个别人看不见的位置。","东西不是凭空消失的——它们只是换了个地方躺着。"],"clues":[{"kw":["轮椅","空轮椅"],"type":"yes","text":"是。秘密就在那辆轮椅的坐垫底下。"},{"kw":["丢东西","失窃","被偷","不见了"],"type":"yes","text":"是。这几个月里，病房里总有人丢东西。"},{"kw":["监控","摄像头","拍不到"],"type":"yes","text":"是。走廊的监控一直什么都没拍到——盲区正好在轮椅那里。"},{"kw":["护工","护士"],"type":"yes","text":"是。她推轮椅的动作，其实是一次一次地在钓鱼。"},{"kw":["藏起来","塞进","藏进"],"type":"yes","text":"是。有人把东西藏进了轮椅里，等没人的时候再取走。"},{"kw":["现金","药瓶","药品"],"type":"yes","text":"是。布袋里装着现金和药，那是病人最容易丢的东西。"},{"kw":["保安室","保安","报警"],"type":"yes","text":"是。她没有喊人，而是直接推着轮椅去了保安室。"},{"kw":["病人家属","家属","亲人"],"type":"no","text":"不是。偷东西的不是病人的家属——他们进不了储物区。"},{"type":"irr","kw":["医院的走"],"text":"与此无关。这一锅和「医院的走」没有关系，汤主把话题拨了回来。"}]},
  {"id":"cat-kettle","title":"一直烧开的水壶","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":1,"par":7,"original":true,"surface":"老人独居，每天傍晚都会把水壶放到炉子上烧开。水开后他也不泡茶，只是掀开壶盖又盖上，让蒸汽从窗口飘出去。邻居都笑他糊涂。直到有一天，水壶没响，邻居立刻打了电话。为什么？","truth":"老人和住在楼下的独居老友约定：每天傍晚烧一次水，让水壶的响声和蒸汽从窗口传下去，算是报平安。老友听见水声，就知道他还好。这天老人烧水时突然晕倒，水壶一直没响；楼下老友等了很久没听见动静，才托邻居打电话——正是这通电话救了老人一命。","truthKeywords":["烧水","水壶","蒸汽","报平安","独居","老友","邻居","晕倒","水声"],"coreKeywords":["报平安","蒸汽","水声"],"hints":["水声不是给他自己听的。","他每天只烧一次，时间从不改变。"],"clues":[{"kw":["烧水","水开","烧开"],"type":"yes","text":"是。每天那壶水，是烧给别人听的。"},{"kw":["报平安","平安","暗号","约定"],"type":"yes","text":"是。水声是他们约定好的那句“我还好”。"},{"kw":["楼下","隔壁","邻居"],"type":"yes","text":"是。真正在意这壶水的人，就住在附近。"},{"kw":["独居","一个人住","独自"],"type":"yes","text":"是。他们两个人，都习惯了一个人过日子。"},{"kw":["晕倒","摔倒","昏迷","发病"],"type":"yes","text":"是。这天他没来得及把水烧开——因为他倒下了。"},{"kw":["救人","救了命","打电话"],"type":"yes","text":"是。那通电话救了他的命。"},{"kw":["泡茶","喝茶","喜欢喝"],"type":"no","text":"不是。他烧水不是为了泡茶，他自己几乎不喝。"},{"kw":["煤气","漏气","火灾"],"type":"no","text":"不是。危险不是从炉子上来的。"},{"type":"irr","kw":["居每天傍"],"text":"与此无关。「居每天傍」不在这个故事里，换个方向问吧。"}]},
  {"id":"cat-chalk","title":"黑板右下角的数字","tag":"悬疑系","cats":["校园","悬疑","推理"],"difficulty":2,"par":8,"original":true,"surface":"高三（2）班有个老规矩：每天早读前，值日生会把当天到校的人数写在黑板右下角。这天早上，数字从 12 变成了 11。班主任看了一眼，脸色大变，立刻让全班停课去找人。为什么？","truth":"黑板右下角的数字，就是当天到校的人数。少了一个，说明有人没到。可班主任知道，这个学生的父母早上刚送他来学校，书包还留在座位上，人却不见了——他没来上课，也没有请假，说明他是在学校里出事的。后来大家在一间废弃的器材室里找到了他：他被人锁在里面，已经困了整整两节课。","truthKeywords":["人数","黑板","值日生","到校","书包","器材室","锁","班主任"],"coreKeywords":["人数","器材室","锁"],"hints":["黑板右下角那个数字，是有含义的。","少的那一个人，早上其实还在学校里。","他没有请假，也没有回家。"],"clues":[{"kw":["人数","写了多少"],"type":"yes","text":"是。黑板右下角的数字，就是当天到校的人数。"},{"kw":["黑板","右下角","值日生"],"type":"yes","text":"是。写数字的位置和写数字的人，都是固定的。"},{"kw":["没来","少了一个","缺席","没到"],"type":"yes","text":"是。数字少了一个，说明有人没到教室。"},{"kw":["书包","座位","东西还在"],"type":"yes","text":"是。他的书包还留在座位上——人却不见了。"},{"kw":["器材室","储藏室","仓库"],"type":"yes","text":"是。最后他是在一间废弃的器材室里被找到的。"},{"kw":["被锁","锁在里面","关起来"],"type":"yes","text":"是。他不是走丢的，是被人关起来了。"},{"kw":["班主任","老师"],"type":"yes","text":"是。最先察觉不对劲的，是每天看这个数字的老师。"},{"kw":["请假","生病","旷课","逃学"],"type":"no","text":"不是。他没有请假，也不是自己不想来。"},{"type":"irr","kw":["高三2班"],"text":"与此无关。汤主摇头：「高三2班」和汤底扯不上。"}]},
  {"id":"cat-bus","title":"末班车的两张票","tag":"催泪系","cats":["温情","催泪","都市"],"difficulty":1,"par":7,"original":true,"surface":"公交司机认得那位老人：他每天坐末班车，上车总是刷两次卡，然后坐到靠窗的第二个位置。有人问他为什么买两张票，他说：“她坐这儿。”可车上明明只有他一个人。为什么？","truth":"老人的妻子生前每天和他一起坐这趟末班车回家，总是坐在靠窗的第二个位置。妻子去世后，老人还是每天刷两次卡，把那个位置留出来——在他心里，她还在车上。司机和常客都知道这件事，从来不去坐那个位置。","truthKeywords":["妻子","老伴","去世","过世","两张票","刷两次","买两张","末班车","最后一班","靠窗","那个位置","留座","公交","司机"],"coreKeywords":["妻子","两张票"],"hints":["他买两张票，不是买错了。","车上那个位置，是有主人的。"],"clues":[{"kw":["两张票","刷两次","买两张"],"type":"yes","text":"是。他每天确实为两个人付钱。"},{"kw":["妻子","老伴","老婆","太太"],"type":"yes","text":"是。那个位置上，坐的一直是他的妻子。"},{"kw":["去世","过世","走了","不在了"],"type":"yes","text":"是。她已经不在了——可他还是每天给她留座。"},{"kw":["末班车","最后一班","晚上"],"type":"yes","text":"是。他们习惯坐的，是每天最后一班车。"},{"kw":["靠窗","第二个位置","那个座位"],"type":"yes","text":"是。那个位置是固定的，从来没人去坐。"},{"kw":["司机","售票员","乘务员"],"type":"yes","text":"是。司机知道这件事，所以从不多问。"},{"kw":["迷路","老年痴呆","糊涂","记错"],"type":"no","text":"不是。他不是糊涂，也不是记错了。"},{"kw":["新乘客","陌生人","别人坐过"],"type":"partial","text":"部分正确。有不知情的新乘客坐过那个位置，但司机和常客都会轻声劝开。"},{"type":"irr","kw":["机认得那"],"text":"与此无关。这一锅和「机认得那」没有关系，汤主把话题拨了回来。"}]},
  {"id":"cat-mirror","title":"镜子上的口红印","tag":"微恐系","cats":["恐怖","微恐","都市传说"],"difficulty":2,"par":8,"original":true,"surface":"女孩租下一间老公寓，卧室墙上有一面钉死的镜子。她从不涂口红。可住进来的第三天早上，她发现镜面上多了一个模糊的口红印，位置在镜子的边缘，像是从镜子背面贴上去的。她当晚就搬走了。为什么？","truth":"那面镜子后面是一道被钉住的暗门，通向隔壁空置的房间。口红印其实贴在镜子的背面，从正面只能看到模糊的一团——有人想让她以为是自己看错了。她掰开镜框，看见暗门的合页上有新蹭掉的漆，知道有人能进她的卧室，于是当晚就搬走并报了警。","truthKeywords":["镜子","暗门","隔壁","口红印","镜框","合页","搬走","报警","背面"],"coreKeywords":["暗门","口红印","镜子"],"hints":["那个印子不是她留下的，也不是从正面画上去的。","镜子的后面，还藏着东西。","有人能进她的房间——只是走的不是门。"],"clues":[{"kw":["镜子","镜面"],"type":"yes","text":"是。关键在镜子本身——它后面还有空间。"},{"kw":["暗门","暗格","密道","夹层"],"type":"yes","text":"是。镜子后面藏着一道暗门。"},{"kw":["口红印","口红","印子"],"type":"yes","text":"是。那个印子贴在镜子背面，再从正面透出来。"},{"kw":["隔壁","邻屋","空房间"],"type":"yes","text":"是。暗门通的是隔壁那间空了很久的屋子。"},{"kw":["镜框","合页"],"type":"yes","text":"是。镜框和合页上有新蹭掉的漆——有人常开它。"},{"kw":["搬走","退租","离开"],"type":"yes","text":"是。她当天就搬走了，一天都不敢多待。"},{"kw":["前租客","房东","室友"],"type":"no","text":"不是。这件事跟房东和前租客没关系——有人根本没走。"},{"kw":["化妆","恶作剧","开玩笑"],"type":"no","text":"不是。不是谁在开玩笑，也不是朋友干的。"},{"type":"irr","kw":["女孩租下"],"text":"与此无关。「女孩租下」不在这个故事里，换个方向问吧。"}]},
  {"id":"cat-icecream","title":"窗台上的冰淇淋","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":2,"par":8,"original":true,"surface":"男人独居，冰箱里永远冻着一支没拆封的冰淇淋。每到周末，他会把它拿出来放在窗台上，过一会儿又放回冰箱。邻居都说他有怪癖，他自己却说，这是他和儿子的约定。为什么？","truth":"儿子小时候每到周末都吵着要吃冰淇淋。后来儿子去外地读书、工作，每次视频都说“下次回来就吃”。男人怕冰淇淋坏了，就每周把它拿到窗台上拍一张照片发给儿子，再放回冰箱——那支冰淇淋，是他在替儿子占着位置。","truthKeywords":["冰淇淋","雪糕","冰箱","窗台","儿子","周末","视频","照片","回家","留着"],"coreKeywords":["冰淇淋","儿子"],"hints":["那支冰淇淋不是给他自己吃的。","每周拿出来一次，是为了让某个人看见。","他在等一个人回家。"],"clues":[{"kw":["冰淇淋","雪糕","冰棍"],"type":"yes","text":"是。那支冰淇淋一直是留给别人的。"},{"kw":["儿子","孩子","小孩"],"type":"yes","text":"是。他心里那个位置上，一直是他儿子。"},{"kw":["窗台","窗口","阳台"],"type":"yes","text":"是。放在窗台上，是为了让远方的人看见。"},{"kw":["照片","拍照","视频"],"type":"yes","text":"是。他每周拍一张发过去，像在说“位置给你留着”。"},{"kw":["周末","每周","每个星期"],"type":"yes","text":"是。这件事只在周末做，因为那是他们原来的约定时间。"},{"kw":["冰箱","冷冻","冻着"],"type":"yes","text":"是。拍完他又放回冰箱——他怕它化了，也怕位置没了。"},{"kw":["过期","坏了","扔掉"],"type":"no","text":"不是。冰淇淋没有过期，他也从来没舍得扔掉。"},{"kw":["去世","病死","车祸"],"type":"irr","text":"与此无关。故事里没有人死去——只是有人还没回来。"}]},
  {"id":"cat-keyboard","title":"没有 F5 的键盘","tag":"悬疑系","cats":["悬疑","职场","反转"],"difficulty":3,"par":9,"original":true,"surface":"新来的会计发现，对面老会计的键盘上，F5 键被人抠掉了，只留下一个黑洞。老会计每天上班第一件事，就是用指甲去戳那个洞。三个月后，新会计查清了账目，老会计被带走。为什么？","truth":"老会计一直在挪用公司的货款。他写了个脚本，只要按 F5，仓库台账就会被自动刷新成一份动过手脚的旧数据，把亏空盖掉。为了防止别人误按露馅，他把 F5 键抠掉了，只有自己知道用指甲去戳那个位置。新会计正是从那个洞开始查，才发现账目被人反复“重置”过。","truthKeywords":["F5","键盘","脚本","台账","挪用","账目","刷新","抠掉","亏空","仓库"],"coreKeywords":["F5","挪用","刷新"],"hints":["被抠掉的那个键，不是坏了。","按一下那个位置，账就会自己“变回去”。","他用指甲戳的不是键，是掩盖。","最后一条：把「F5」和「挪用」连起来想想——它们之间差了什么？"],"clues":[{"kw":["F5","F5键"],"type":"yes","text":"是。被抠掉的那个键，本身就是答案。"},{"kw":["键盘","按键","抠掉"],"type":"yes","text":"是。键盘上少了一个键——是被人故意抠掉的。"},{"kw":["脚本","程序"],"type":"yes","text":"是。那个键会触发一段别人看不见的程序。"},{"kw":["台账","账目","库存表","数据"],"type":"yes","text":"是。一按下去，账目就会被刷成另一份。"},{"kw":["挪用","贪污","做假账"],"type":"yes","text":"是。他一直在偷偷挪用公司的钱。"},{"kw":["掩盖","盖掉","隐藏"],"type":"yes","text":"是。按那一下，是为了把亏空盖掉。"},{"kw":["误按","别人按","同事按"],"type":"no","text":"不是。抠掉它是怕别人无意间按到，把破绽露出来。"},{"kw":["失灵","故障","接触不良"],"type":"no","text":"不是。键盘没坏，F5 也没失灵——是有人不让它存在。"},{"type":"irr","kw":["新来的会"],"text":"与此无关。汤主摇头：「新来的会」和汤底扯不上。"}]},
  {"id":"cat-rope","title":"阳台垂下的绳子","tag":"悬疑系","cats":["温情","悬疑","都市"],"difficulty":2,"par":8,"original":true,"surface":"男人住在六楼，七楼阳台上常年垂着一条打了结的旧绳子，绳尾刚好停在他家窗边。他每天出门前都会拉一下那条绳子。某天早上，他连拉三下都没有回应，立刻请了假，报了警。为什么？","truth":"七楼住着一位独居老人。老人腿脚不便，和男人约好：每天男人出门前拉一下绳子，老人在上面回拉一下，表示自己还好。这天老人没有回拉，男人知道他出事了，于是报警。警察破门时，老人已经中风倒在地上，因为送医及时保住了命。","truthKeywords":["绳子","老人","独居","回拉","中风","报警","约定","七楼"],"coreKeywords":["绳子","回拉","中风"],"hints":["那条绳子不是晾衣服用的。","他拉的每一下，都是在问一句话。","绳子那头的人，需要有人知道他还在。"],"clues":[{"kw":["绳子","打了结","绳尾"],"type":"yes","text":"是。那条绳子是两个人之间的联络线。"},{"kw":["老人","独居老人","楼上住户"],"type":"yes","text":"是。绳子那头是一位独自生活的老人。"},{"kw":["回拉","回应","拉一下"],"type":"yes","text":"是。他们约好：他拉一下，上面回拉一下。"},{"kw":["中风","摔倒","发病","晕倒"],"type":"yes","text":"是。那天老人突发中风，倒在地上动不了。"},{"kw":["报警","警察","破门","求救"],"type":"yes","text":"是。他报警，警察破门才救回了老人。"},{"kw":["七楼","正上方","楼上的"],"type":"yes","text":"是。老人就住在他家正上方。"},{"kw":["晾衣服","晒被子","洗衣服"],"type":"no","text":"不是。绳子从来不是用来晾衣服的。"},{"kw":["搬家","出差","旅游"],"type":"no","text":"不是。老人没有搬走，也没有出门。"},{"type":"irr","kw":["男人住在"],"text":"与此无关。这一锅和「男人住在」没有关系，汤主把话题拨了回来。"}]},
  {"id":"cat-timer","title":"凌晨三点的闹钟","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":2,"par":8,"original":true,"surface":"同事发现男人手机里有十几个闹钟，从凌晨两点半到三点半，每隔十分钟一个。男人白天精神很好，从不迟到。同事笑他睡不好，他却说，这些闹钟救过他母亲的命。为什么？","truth":"男人和母亲住在一起，母亲患有重病，夜里需要定时吃药、翻身。他把闹钟设成一长串，是怕自己睡得太沉错过时间。有一次他实在太累没听见，母亲差点出事；从那以后，他再也不敢只设一个闹钟。","truthKeywords":["母亲","妈妈","闹钟","定时","吃药","喂药","翻身","重病","照顾","夜里"],"coreKeywords":["母亲","闹钟","吃药"],"hints":["那串闹钟不是为他自己设的。","每隔十分钟一个，是因为有一个时间不能错过。","他怕的不是迟到，是睡得太沉。"],"clues":[{"kw":["闹钟","定时","设了十几个"],"type":"yes","text":"是。那串闹钟是为了不让自己睡得太沉。"},{"kw":["母亲","妈妈","老人"],"type":"yes","text":"是。他要照顾的是自己的母亲。"},{"kw":["吃药","喂药","服药"],"type":"yes","text":"是。有一个时间点必须起来喂药，一分钟都不能差。"},{"kw":["翻身","换姿势","褥疮"],"type":"yes","text":"是。母亲夜里需要定时翻身，不然会出问题。"},{"kw":["重病","病重","住院","生病"],"type":"yes","text":"是。母亲病得很重，夜里离不开人。"},{"kw":["睡过头","没听见","睡死"],"type":"yes","text":"是。他曾经漏掉过一次，差点出事。"},{"kw":["失眠","睡不好","熬夜"],"type":"no","text":"不是。他白天精神很好，也不是睡不着。"},{"kw":["迟到","上班","工作"],"type":"no","text":"不是。这些闹钟跟上班迟到没有关系。"},{"type":"irr","kw":["同事发现"],"text":"与此无关。「同事发现」不在这个故事里，换个方向问吧。"}]},
  {"id":"o-ticket","title":"半张电影票","tag":"悬疑系","cats":["悬疑","推理","都市"],"difficulty":2,"par":8,"original":true,"surface":"男人在电影院门口捡到半张被撕开的电影票。他看了一眼上面的座位号，立刻走进影厅，径直找到一个陌生人，然后报了警。为什么？","truth":"他的女儿三天前在这家影院失踪。最后一张监控照片里，她手里捏着一张电影票的右半边，边缘是被人撕开的。男人把那半张残票留了下来。今天他捡到的这半张，正好能和自己手里那半拼起来——同一场次、同一排、同一个座位号。他按座位号找到坐在那里的人，那人正是三天前坐在女儿身边的陌生人。他当场报警，警方由此锁定了嫌疑人。","truthKeywords":["女儿","失踪","电影票","半张","撕开","座位号","拼起来","陌生人","监控","照片","嫌疑人","报警"],"coreKeywords":["电影票","半张","座位号"],"hints":["他手里本来就有一半——今天捡到的是另一半。","两半张票能拼在一起，说明什么？","座位号指向的不是一个位置，是一个人。"],"clues":[{"kw":["女儿","小女孩","他的孩子"],"type":"yes","text":"是。他要找的那个人，是他的女儿。"},{"kw":["失踪","不见了","没回家"],"type":"yes","text":"是。他的女儿三天前失踪了，一直没有消息。"},{"kw":["半张票","撕开","拼起来","两半"],"type":"yes","text":"是。这两半张票，本来就是同一张。"},{"kw":["电影票","票根"],"type":"yes","text":"是。关键就是这张电影票——它被人撕成了两半。"},{"kw":["座位号","同一排","同一个位置"],"type":"yes","text":"是。座位号对得上——他们坐的是同一个位置。"},{"kw":["陌生人","旁边的人","那个人"],"type":"yes","text":"是。他找到的，是那天坐在女儿旁边的人。"},{"kw":["报警","嫌疑人","警察"],"type":"yes","text":"是。他当场报了警，警方据此锁定了嫌疑人。"},{"kw":["监控","照片","最后一张"],"type":"yes","text":"是。他手里那张监控照片，拍到了这半张票。"},{"kw":["抢劫","小偷","钱包"],"type":"no","text":"不是。他不是来抓小偷的，票也不是偷来的。"},{"kw":["电影剧情","导演","片子"],"type":"irr","text":"与此无关。放的是什么电影，一点都不重要。"}]},
  {"id":"o-pager","title":"只响一次的寻呼机","tag":"悬疑系","cats":["悬疑","推理","反转"],"difficulty":2,"par":8,"original":true,"surface":"男人的寻呼机响了，屏幕上只有一串数字：六个 0。他看了一眼，脸色骤变，立刻报了警，连夜赶回老家。为什么？","truth":"他和独居老家的父亲约定过一套数字暗号：父亲不识字，只能按寻呼台的数字键。六个 0 是他们说好的“家里出事了，别一个人回来”。男人立刻明白父亲遇险，而且能碰到寻呼机的人已经进了父亲的家。他先报警，再连夜赶回去，可惜还是晚了一步。","truthKeywords":["父亲","寻呼机","数字","暗号","六个0","约定","老家","独居","报警","出事了"],"coreKeywords":["寻呼机","暗号","六个0"],"hints":["这串数字不是号码，是一句话。","父亲不识字，只能用数字说话。","六个 0，是他们约定里最严重的那一句。"],"clues":[{"kw":["父亲","爸爸","老人"],"type":"yes","text":"是。发来这串数字的，是他的父亲。"},{"kw":["寻呼机","BP机","传呼"],"type":"yes","text":"是。那台寻呼机，是父子俩唯一的联络工具。"},{"kw":["暗号","约定","说好的"],"type":"yes","text":"是。这串数字不是号码，是一句约定好的话。"},{"kw":["六个0","000000","六个零"],"type":"yes","text":"是。六个 0，是他们约定的最严重的那一句。"},{"kw":["老家","独居","一个人住"],"type":"yes","text":"是。父亲一个人在老家生活。"},{"kw":["出事","危险","遇险"],"type":"yes","text":"是。这串数字的意思是：家里出事了。"},{"kw":["报警","警察"],"type":"yes","text":"是。他先报了警，再连夜赶回去。"},{"kw":["中奖","诈骗","推销","广告"],"type":"no","text":"不是。这不是诈骗短信，也不是什么中奖通知。"},{"kw":["拨错","按错","误触"],"type":"no","text":"不是。父亲没有按错——那串数字是他一下一下按出来的。"},{"kw":["加班","公司","同事"],"type":"irr","text":"与此无关。他的工作跟这串数字没有关系。"}]},
  {"id":"o-bookshop","title":"书店里的常客","tag":"催泪系","cats":["温情","催泪","都市"],"difficulty":1,"par":7,"original":true,"surface":"书店老板每天打烊前，都会把靠窗那张桌子上的书原样摆好，再把椅子推回去。那张桌子从没人坐过。有人问他为什么，他说：“他今天来过了。”为什么？","truth":"老板的弟弟生前每天下午都来书店，坐在靠窗那张桌子看书。弟弟去世后，老板依旧每天把那张桌子擦干净、把书摆成他习惯的样子，还替他把书翻到下一页——那是他纪念弟弟的方式。他说的“他今天来过了”，其实是他自己替弟弟来过。","truthKeywords":["弟弟","去世","书店","靠窗","那张桌子","每天","纪念","习惯","翻到下一页","打烊"],"coreKeywords":["弟弟","靠窗","纪念"],"hints":["那张桌子是有主人的。","他不是在收拾，是在打招呼。"],"clues":[{"kw":["弟弟","亲弟弟","手足"],"type":"yes","text":"是。那张桌子，属于他的弟弟。"},{"kw":["去世","过世","不在了"],"type":"yes","text":"是。弟弟已经不在了。"},{"kw":["靠窗","窗边","那张桌子"],"type":"yes","text":"是。那个位置，是弟弟固定坐的地方。"},{"kw":["书店","打烊","关门"],"type":"yes","text":"是。这件事发生在书店里，在每天打烊之前。"},{"kw":["翻到下一页","原样摆好","每天摆"],"type":"yes","text":"是。他每天都替弟弟把书翻到下一页。"},{"kw":["纪念","怀念","想念"],"type":"yes","text":"是。这是他想念弟弟的方式。"},{"kw":["顾客","客人","陌生人"],"type":"no","text":"不是。那张桌子不是给客人留的。"},{"kw":["等人","预约","订座"],"type":"no","text":"不是。他不是在等一个还活着的人。"},{"kw":["生意","赚钱","租金"],"type":"irr","text":"与此无关。书店的生意跟这件事没有关系。"}]},
  {"id":"o-snowman","title":"不会化的雪人","tag":"微恐系","cats":["恐怖","微恐","家庭"],"difficulty":2,"par":8,"original":true,"surface":"小女孩在院子里堆了个雪人，天晴了三天，别的雪都化了，只有这个雪人一点没变。妈妈看了一眼雪人的位置，当晚就带着女儿搬走了。为什么？","truth":"雪人堆在院子角落，正压着一块新翻过的土。妈妈发现别处的雪都化了，只有这里不化，是因为土下一直在往外冒冷气。院子下面有一间房东锁着的地下室，里面藏着一台大功率冷柜，排气管被人接到了那块土里。她当晚就带着女儿搬走，随后报警——警方在地下室的冷柜里找到了一具尸体。","truthKeywords":["雪人","不化","冷气","地下室","冷柜","排气管","尸体","新翻的土","房东","报警","搬走"],"coreKeywords":["雪人","冷气","冷柜"],"hints":["那个雪人底下，有东西在往外冒。","院子下面还有一间屋子，她从来没进去过。","能让雪不化的，不是天气。"],"clues":[{"kw":["雪人","堆的雪人"],"type":"yes","text":"是。那个雪人下面，藏着别的东西。"},{"kw":["不化","没化","冷气","寒气"],"type":"yes","text":"是。它不化，是因为底下一直在往外冒冷气。"},{"kw":["地下室","地窖","地下"],"type":"yes","text":"是。院子下面有一间锁着的地下室。"},{"kw":["冷柜","冰柜","制冷"],"type":"yes","text":"是。地下室里有一台大功率冷柜。"},{"kw":["排气管","管道","接到土里"],"type":"yes","text":"是。冷柜的排气管被人接到了那块土里。"},{"kw":["尸体","死人","藏着的东西"],"type":"yes","text":"是。冷柜里藏着一具尸体。"},{"kw":["房东","不许进","锁着"],"type":"yes","text":"是。房东一直不许她靠近那间地下室。"},{"kw":["报警","搬走","警察"],"type":"yes","text":"是。她当晚就搬走，然后报了警。"},{"kw":["童话","魔法","神仙"],"type":"no","text":"不是。这不是童话，雪人没有魔法。"},{"kw":["天气","气温","下雪"],"type":"irr","text":"与此无关。那几天天气很晴，跟下雪没有关系。"}]},
  {"id":"o-wednesday","title":"重复的周三","tag":"悬疑系","cats":["脑洞","科幻","反转"],"difficulty":3,"par":10,"original":true,"surface":"男人发现自己的手机日历停在同一个周三，已经连续 27 天了。他不慌不忙，每天照常上班、照常回家。第 28 天，他走进了一家珠宝店。为什么？","truth":"男人被困在一个不断重复的周三里，只有他记得每一天。他试过各种办法都逃不出去，后来发现：循环里唯一没变过的，是珠宝店橱窗里那枚戒指——那是他和妻子结婚纪念日想买却没舍得买的。第 28 天，他用这些天里摸清的价格和时机买下了那枚戒指，然后赶去医院。他终于明白，循环开始的那一天，正是妻子出事的那一天；他要做的不是逃出去，而是在这一天结束之前，把戒指送到她手上。","truthKeywords":["时间循环","重复","周三","只有他记得","戒指","珠宝店","妻子","医院","结婚纪念日","逃出去"],"coreKeywords":["时间循环","戒指","妻子"],"hints":["他不是不在意，是已经试过太多次了。","循环里唯一没变过的东西，就是线索。","他最后想做的，不是离开这一天。","最后一条：把「时间循环」和「戒指」连起来想想——它们之间差了什么？"],"clues":[{"kw":["时间循环","循环","重复同一天"],"type":"yes","text":"是。他被困在同一个周三里，一遍一遍地重来。"},{"kw":["只有他记得","别人不记得","只有他知道"],"type":"yes","text":"是。循环里只有他记得发生过什么。"},{"kw":["周三","日历","同一天"],"type":"yes","text":"是。重复的，永远是那一个周三。"},{"kw":["戒指","珠宝店","橱窗"],"type":"yes","text":"是。那枚戒指是他在循环里唯一没变过的线索。"},{"kw":["妻子","老婆","太太"],"type":"yes","text":"是。他要找的人是自己的妻子。"},{"kw":["医院","病房","出事了"],"type":"yes","text":"是。循环开始的那天，妻子在医院出事了。"},{"kw":["结婚纪念日","纪念日","舍不得买"],"type":"yes","text":"是。那枚戒指本来是他们纪念日要买的。"},{"kw":["不逃","留下来","完成一件事"],"type":"yes","text":"是。他最后放弃了逃出去，转而想在循环里做完一件事。"},{"kw":["做梦","幻觉","精神病"],"type":"no","text":"不是。这不是梦，也不是幻觉。"},{"kw":["手机坏了","系统故障","日历错了"],"type":"no","text":"不是。手机没有坏，日历也没有错。"},{"kw":["加班","同事","领导"],"type":"irr","text":"与此无关。上班只是他用来打发循环的方式。"}]},
  {"id":"o-rollcall","title":"点名时多出的那声「到」","tag":"悬疑系","cats":["恐怖","校园","怪谈"],"difficulty":2,"par":8,"original":true,"surface":"班主任每晚都会对着空教室点一次名，点到最后一个名字时，走廊的灯会闪一下。这晚她照常点名，念到那个名字时，教室后排传来了一声“到”。她合上名册，第二天就办了退休。为什么？","truth":"那个名字是三年前一个在教室里猝死的学生的。班主任一直自责当年没及时发现，于是每晚都对着空教室点一次名，像是在道歉——三年来从没人应过。这晚后排却传来一声“到”。她走过去，发现是一个每天偷偷躲在教室过夜的孩子：那孩子以为她在叫自己。她这才知道，自己每晚点名时，教室里一直有别人在听。第二天，她办了退休，也替那个孩子联系了救助站。","truthKeywords":["点名","空教室","名字","猝死","学生","三年前","自责","后排","过夜","退休"],"coreKeywords":["点名","猝死","后排"],"hints":["她点的是一个已经不在的人。","应声的人，其实一直都在教室里。","那不是鬼——是一个活着的孩子。"],"clues":[{"kw":["点名","念名字","名册"],"type":"yes","text":"是。她每晚都在对着一间空教室点名。"},{"kw":["猝死","死了","去世"],"type":"yes","text":"是。那个名字的主人，三年前在教室里死了。"},{"kw":["学生","同学","孩子"],"type":"yes","text":"是。那是一个学生的名字。"},{"kw":["自责","内疚","道歉"],"type":"yes","text":"是。她点名，其实是在道歉。"},{"kw":["空教室","没有人","空着"],"type":"yes","text":"是。那间教室每天晚上都是空的。"},{"kw":["后排","应声"],"type":"yes","text":"是。这晚有人在后排应了一声。"},{"kw":["过夜","偷偷"],"type":"yes","text":"是。应声的是一个偷偷在教室过夜的孩子。"},{"kw":["退休","辞职","离开"],"type":"yes","text":"是。第二天她就办了退休。"},{"kw":["闹鬼","灵异"],"type":"no","text":"不是。应声的不是鬼，是一个活着的孩子。"},{"kw":["考试","成绩","升学"],"type":"irr","text":"与此无关。这跟成绩和升学没有关系。"}]},
  {"id":"o-clock","title":"拨慢三分钟的挂钟","tag":"推理系","cats":["推理","反转","职场"],"difficulty":2,"par":8,"original":true,"surface":"老修表匠退休前，把自己店里那口挂钟的指针拨慢了三分钟，然后锁门离开。第二天，这条街上唯一一家准时开门的店，是他的。为什么？","truth":"这条街上的店主都习惯出门前抬头看一眼他那口挂钟，用它来对时间。老修表匠把钟拨慢了三分钟，别家看到的时间就比实际早了，于是比平时晚三分钟开门；而他自己按标准时间开门，自然成了街上最早的那一家。这是他给自己准备的退休礼物——最后一天，让整条街都记住他的钟。","truthKeywords":["挂钟","拨慢","三分钟","对时间","开门","最早","修表匠","退休","这条街"],"coreKeywords":["挂钟","拨慢","三分钟"],"hints":["这条街上，很多人都靠他那口钟过日子。","钟慢了三分钟，别家的人就会跟着慢。","他不改自己的表，只改别人看的时间。"],"clues":[{"kw":["挂钟","那口钟","墙上的钟"],"type":"yes","text":"是。关键就是他店里那口挂钟。"},{"kw":["拨慢","调慢","动过"],"type":"yes","text":"是。他在离开前把钟拨慢了。"},{"kw":["三分钟","几分钟"],"type":"yes","text":"是。不多不少，正好慢了三分钟。"},{"kw":["对时间","看时间","抬头看"],"type":"yes","text":"是。这条街的店主都习惯看他的钟对时间。"},{"kw":["开门","最早","第一家"],"type":"yes","text":"是。他成了这条街上最早开门的那家。"},{"kw":["退休","最后一天","关店"],"type":"yes","text":"是。那天是他退休前的最后一天。"},{"kw":["修表匠","修表","表匠"],"type":"yes","text":"是。拨钟的人，就是修了一辈子表的那位匠人。"},{"kw":["坏了","故障","停了"],"type":"no","text":"不是。钟没坏，也没有停。"},{"kw":["偷东西","报复","害人"],"type":"no","text":"不是。他不是为了害谁，也没偷东西。"},{"kw":["客人","生意","赚钱"],"type":"irr","text":"与此无关。这跟当天的生意好坏没有关系。"}]},
  {"id":"o-nightlamp","title":"值夜班的那盏灯","tag":"催泪系","cats":["温情","催泪","医院"],"difficulty":1,"par":7,"original":true,"surface":"医院走廊尽头有一盏灯，每晚十二点准时亮起，凌晨两点准时熄灭。护士们都以为它坏了。新来的护士查了排班表，第二天买了一个蛋糕，送到了走廊尽头那间病房。为什么？","truth":"那间病房住着一位老太太，她的丈夫年轻时是这层楼的老电工。丈夫去世前，把走廊那盏灯改成了定时开关，每晚十二点到两点亮着——那是他上夜班时回家的时间。老太太每晚都等这盏灯亮起才肯睡。新护士查排班表，发现那两天正是老太太丈夫的忌日，于是买了个蛋糕，陪老太太一起等灯。","truthKeywords":["灯","十二点","两点","老太太","丈夫","电工","定时","忌日","病房","夜班"],"coreKeywords":["灯","丈夫","定时"],"hints":["那盏灯不是坏了，是有人在替它安排时间。","亮灯的时间，是某个人回家的时间。"],"clues":[{"kw":["那盏灯","走廊的灯"],"type":"yes","text":"是。那盏灯不是坏了，是被人设成了定时。"},{"kw":["定时","定时开关","自动"],"type":"yes","text":"是。它亮和灭的时间，是被人提前设好的。"},{"kw":["十二点","两点"],"type":"yes","text":"是。每晚十二点亮，两点灭，一天不差。"},{"kw":["老太太","老人","病人"],"type":"yes","text":"是。这盏灯是留给一位老太太看的。"},{"kw":["丈夫","老伴","老公"],"type":"yes","text":"是。设这盏灯的人，是她的丈夫。"},{"kw":["电工","修电","接电线"],"type":"yes","text":"是。她的丈夫以前是这层楼的老电工。"},{"kw":["忌日","纪念","去世"],"type":"yes","text":"是。那两天正是她丈夫的忌日。"},{"kw":["蛋糕","陪她","陪着"],"type":"yes","text":"是。新护士买了个蛋糕，去陪她一起等灯。"},{"kw":["短路","电路故障","坏了"],"type":"no","text":"不是。线路没有故障，灯也没坏。"},{"kw":["值班","排班","工资"],"type":"irr","text":"与此无关。这跟排班和工资没有关系。"}]},
  {"id":"o-shoes","title":"门口多出的一双鞋","tag":"微恐系","cats":["恐怖","微恐","家庭"],"difficulty":3,"par":9,"original":true,"surface":"独居的男人回家，发现门口多了一双鞋，鞋头朝里，摆得很整齐。他没有进去，而是退到楼下报了警。为什么？","truth":"男人每天出门前都会把一双旧鞋留在门口，鞋头朝外。这天他回来，门口却多了一双鞋，鞋头朝里摆得整整齐齐。他家的门只有在屋里才能反锁——也就是说，那个人还在屋里。鞋头朝里，是进屋脱鞋的人的习惯；他没敢进去，退到楼下直接报了警。警察破门时，屋里的人还在翻抽屉。","truthKeywords":["鞋","鞋头朝里","门口","反锁","有人进了屋","翻抽屉","报警","独居","旧鞋"],"coreKeywords":["鞋头朝里","反锁","有人进了屋"],"hints":["他自己那双鞋，鞋头是朝外的。","多出来的这双鞋，朝里的方向说明了什么？","他家的门，只有从里面才能锁上。","最后一条：把「鞋头朝里」和「反锁」连起来想想——它们之间差了什么？"],"clues":[{"kw":["多了一双鞋","门口的鞋"],"type":"yes","text":"是。关键就在门口那双鞋上。"},{"kw":["朝里","鞋头朝里","摆得整齐"],"type":"yes","text":"是。鞋头朝里，说明脱鞋的人进了屋，还没走。"},{"kw":["反锁","从里面锁","门锁"],"type":"yes","text":"是。他家的门只有在屋里才能反锁。"},{"kw":["有人进了屋","进过屋","小偷"],"type":"yes","text":"是。有人进过他的屋子，而且可能还在里面。"},{"kw":["报警","警察","破门"],"type":"yes","text":"是。他没有进去，而是退到楼下报了警。"},{"kw":["翻抽屉","找东西","被翻过"],"type":"yes","text":"是。警察破门时，那个人还在翻抽屉。"},{"kw":["独居","一个人住","自己住"],"type":"yes","text":"是。他一个人住，屋里不该有第二个人。"},{"kw":["家人","妻子","孩子"],"type":"no","text":"不是。那不是家人的鞋，他一个人住。"},{"kw":["快递","外卖","送错"],"type":"no","text":"不是。不是快递或外卖放错了地方。"},{"kw":["邻居","楼上","隔壁"],"type":"irr","text":"与此无关。这件事跟邻居没有关系。"}]},
  {"id":"o-busstop","title":"同一个站台","tag":"悬疑系","cats":["悬疑","推理","旅途"],"difficulty":2,"par":8,"original":true,"surface":"女人每周三都在同一个公交站台等车，从不坐车，只在站牌下站十分钟就走。三年后的某个周三，她第一次上了车。为什么？","truth":"她的丈夫三年前在这个站台等车时，被一辆闯红灯的车撞死了。那天正是周三，也是他们约好一起等车的时间。此后三年，女人每周三都来站牌下站十分钟——她在等他。直到那个肇事司机被判刑的这天，她才第一次上了那班车，去城郊的墓地看他。","truthKeywords":["站台","公交","周三","丈夫","车祸","等车","肇事司机","判刑","墓地","三年"],"coreKeywords":["站台","周三","丈夫"],"hints":["她来站台，不是为了坐车。","周三这个日子，是他们约好的。","她第一次上车的那天，有件事终于了结。"],"clues":[{"kw":["丈夫","老公","爱人"],"type":"yes","text":"是。她等的人，是自己的丈夫。"},{"kw":["站台","公交站","站牌"],"type":"yes","text":"是。那个站台是他们约好见面的地方。"},{"kw":["周三","每周三"],"type":"yes","text":"是。她只挑周三来，一天都不差。"},{"kw":["车祸","撞死","事故"],"type":"yes","text":"是。她的丈夫在这里出了车祸。"},{"kw":["等车","一起等","约好"],"type":"yes","text":"是。他们本来约好一起等那班车。"},{"kw":["肇事司机","判刑","司机"],"type":"yes","text":"是。这天，肇事司机终于被判了刑。"},{"kw":["墓地","看他"],"type":"yes","text":"是。她第一次上车，是去墓地看他。"},{"kw":["三年","三年前"],"type":"yes","text":"是。这件事已经过去三年了。"},{"kw":["上班","通勤","换乘"],"type":"no","text":"不是。她不是来上班或换乘的。"},{"kw":["迟到","堵车","末班车"],"type":"irr","text":"与此无关。这跟迟到和堵车没有关系。"}]},
  {"id":"o-lottery","title":"撕碎的头奖彩票","tag":"悬疑系","cats":["悬疑","推理","反转"],"difficulty":3,"par":9,"original":true,"surface":"男人每周都买同一组号码，十年从没改过。这一次，他中了头奖。可他在妻子面前把彩票撕得粉碎，第二天一早就走进了派出所。为什么？","truth":"十年前，他酒后开车撞倒了一个骑车人，因为害怕，他逃了。那张从对方身上掉落的工作证，他记了一路——上面的编号，被他当成了彩票号码，十年每周买一次。他买这组号码，不是为了中奖，是为了逼自己记住那件事，等哪天有勇气去自首。中奖那天他忽然明白：这不是运气，是那个人在提醒他。于是他撕了彩票，走进了派出所自首。","truthKeywords":["彩票","号码","中奖","头奖","肇事逃逸","撞倒","逃逸","自首","工作证","编号","十年","内疚"],"coreKeywords":["肇事逃逸","号码","自首"],"hints":["他买这组号码，从来不是为了中奖。","那组数字有出处——来自一个他永远忘不掉的地方。","他撕的不是钱，是一个瞒了十年的秘密。","最后一条：把「肇事逃逸」和「号码」连起来想想——它们之间差了什么？"],"clues":[{"kw":["彩票","买号码","一组号码"],"type":"yes","text":"是。那组号码的来历，才是这道汤的底。"},{"kw":["中奖","头奖","中了"],"type":"yes","text":"是。他确实中了头奖——可他一点都不高兴。"},{"kw":["肇事","撞人","车祸","逃逸"],"type":"yes","text":"是。十年前他开车撞了人，然后逃了。"},{"kw":["自首","派出所","投案"],"type":"yes","text":"是。第二天一早，他走进了派出所自首。"},{"kw":["工作证","证件","编号"],"type":"yes","text":"是。号码的出处，是那个被撞的人掉落的工作证。"},{"kw":["十年","每周","一直买"],"type":"yes","text":"是。这组号码他买了十年，一次都没改过。"},{"kw":["妻子","老婆","家人"],"type":"yes","text":"是。他当着妻子的面撕掉了彩票。"},{"kw":["撕掉","撕碎","不要了"],"type":"yes","text":"是。他亲手把到手的大奖撕了。"},{"kw":["做梦","预知","神仙托梦"],"type":"no","text":"不是。没有人托梦，号码也不是算出来的。"},{"kw":["赌债","欠钱","破产"],"type":"irr","text":"与此无关。他并不缺钱，也没有赌债。"}]},
  {"id":"o-recipe","title":"少一味料的菜谱","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":1,"par":7,"original":true,"surface":"母亲去世后，女人照着母亲手写的菜谱做菜，可每一道都差一点味道。她把分量称得一丝不差，还是做不出来。直到她翻到菜谱最后一页，哭了。为什么？","truth":"菜谱最后一页写着一行小字：“给女儿的这份，记得多放一勺糖。”原来母亲每次给她盛的那一份，都偷偷多加了一勺。她照着菜谱称得再准，也复刻不出母亲多给的那一勺——那多出来的一点，才是母亲的味道。","truthKeywords":["菜谱","母亲","少一味","多放一勺","多一勺","糖","味道","分量","最后一页","偷偷多加"],"coreKeywords":["菜谱","多放一勺","母亲"],"hints":["菜谱上的分量，其实一直是对的。","她少的那一味，不在配料表里。"],"clues":[{"kw":["菜谱","手写的","菜谱本"],"type":"yes","text":"是。秘密就在那本手写菜谱里。"},{"kw":["多放一勺","多一勺","多加"],"type":"yes","text":"是。她少的正是那一勺——母亲每次都偷偷多加。"},{"kw":["母亲","妈妈","她妈"],"type":"yes","text":"是。写下这行字的人，是她的母亲。"},{"kw":["最后一页","最后一页的字","小字"],"type":"yes","text":"是。答案写在菜谱的最后一页。"},{"kw":["分量","称重","配料"],"type":"yes","text":"是。她分量称得没错，错的是她不知道有“多出来”的那一份。"},{"kw":["甜的","偏甜"],"type":"yes","text":"是。多出来的那一勺，是糖。"},{"kw":["味道","味道不对","差一点"],"type":"yes","text":"是。她怎么都做不出母亲的味道。"},{"kw":["别人","亲戚","厨师"],"type":"no","text":"不是。菜谱没有传给过别人，也不是谁教错了。"},{"kw":["火候"],"type":"irr","text":"与此无关。锅和火候都没有问题。"}]},
  {"id":"o-tape","title":"母带里的第四条音轨","tag":"悬疑系","cats":["悬疑","推理","职场"],"difficulty":3,"par":10,"original":true,"surface":"录音师整理一批旧母带时，发现一首二十年前的三重唱里，多出了第四条音轨。他听完整个人僵住，随后报了警。为什么？","truth":"那场录音的当晚，录音棚失火，三名歌手遇难。当年的调查里，有一个同事声称自己早就离开了，因此不在现场。可这盘母带的第四条音轨里，清清楚楚录着那个人的和声，而且唱到一半就停了——因为火就是那时候烧起来的。他不仅在场，还锁上了通往楼梯的那扇门。录音师把母带交给了警方。","truthKeywords":["母带","音轨","第四条","和声","三重唱","录音棚","火灾","失火","遇难","在场","锁门","不在场证明"],"coreKeywords":["音轨","火灾","在场"],"hints":["那首歌当年只录了三个人。","第四条音轨里的人，唱到一半就停了。","当年有一个人说，他那天根本不在。","最后一条：把「音轨」和「火灾」连起来想想——它们之间差了什么？"],"clues":[{"kw":["母带","磁带","旧录音"],"type":"yes","text":"是。关键就是那盘二十年前的母带。"},{"kw":["音轨","第四条","多出来的"],"type":"yes","text":"是。那首歌里多出了一条没人唱过的音轨。"},{"kw":["火灾","失火","着火"],"type":"yes","text":"是。录音的当晚，录音棚失火了。"},{"kw":["遇难","死了","烧死"],"type":"yes","text":"是。有三个人死在那场火里。"},{"kw":["在场","在现场","不在场"],"type":"yes","text":"是。有人当年说自己不在，可音轨证明他在。"},{"kw":["锁门","锁上","堵住"],"type":"yes","text":"是。他还锁上了通往楼梯的那扇门。"},{"kw":["和声","唱歌","声音"],"type":"yes","text":"是。第四条音轨里，是那个人的和声。"},{"kw":["报警","警察","交给警方"],"type":"yes","text":"是。录音师把这盘母带交给了警方。"},{"kw":["唱错","走音","剪辑失误"],"type":"no","text":"不是。那不是剪辑失误，也不是谁唱错了。"},{"kw":["设备故障","电路老化","意外"],"type":"partial","text":"部分正确。起火确实起于设备，但门不是自己锁上的。"},{"type":"irr","kw":["录音师整"],"text":"与此无关。汤主摇头：「录音师整」和汤底扯不上。"}]},
  {"id":"o-milk","title":"退订不掉的牛奶","tag":"微恐系","cats":["恐怖","微恐","都市传说"],"difficulty":3,"par":9,"original":true,"surface":"女人一个人住，订了一个月的牛奶。一个月后她退了订，可每天清晨门口还是会出现一瓶牛奶。她装了摄像头，看完录像当晚就搬走了。为什么？","truth":"录像里，凌晨四点有人把新牛奶放下，再把前一天那瓶拿走——那是住在楼上的邻居。他把牛奶放在她门口，是为了确认她的作息：只要前一天那瓶一直没人拿进屋，就说明她不在家。这几个月她家被翻过好几次，都是从门锁正常打开的。她当晚就搬走并报了警。","truthKeywords":["牛奶","退订","摄像头","录像","凌晨","邻居","作息","不在家","踩点","翻过","搬走","报警"],"coreKeywords":["牛奶","退订","踩点"],"hints":["她退订了，可送奶的人从没停过。","那瓶牛奶不是给她喝的，是给她“证明”的。","有人想知道的，是她每天在不在家。","最后一条：把「牛奶」和「退订」连起来想想——它们之间差了什么？"],"clues":[{"kw":["牛奶","奶瓶","门口的牛奶"],"type":"yes","text":"是。那瓶牛奶不是给她喝的，是一个信号。"},{"kw":["退订","不订了","取消"],"type":"yes","text":"是。她明明退订了，牛奶却一天没断。"},{"kw":["摄像头","录像","监控"],"type":"yes","text":"是。录像拍到了那个每天来放牛奶的人。"},{"kw":["凌晨","四点","天没亮"],"type":"yes","text":"是。他每天凌晨四点来，从不出声。"},{"kw":["邻居","楼上","住在附近"],"type":"yes","text":"是。放牛奶的人，就住在这栋楼里。"},{"kw":["作息","在不在家","有没有人"],"type":"yes","text":"是。那瓶牛奶是用来判断她在不在家的。"},{"kw":["翻过","进过屋","被翻"],"type":"yes","text":"是。她家已经被翻过好几次了。"},{"kw":["搬走","报警","警察"],"type":"yes","text":"是。她当晚就搬走，然后报了警。"},{"kw":["送错了","奶站","订奶"],"type":"no","text":"不是。不是奶站送错了，也不是系统没退订。"},{"kw":["恶作剧","追求者","暗恋"],"type":"no","text":"不是。这不是恶作剧，也不是有人在追求她。"},{"type":"irr","kw":["女人一个"],"text":"与此无关。这一锅和「女人一个」没有关系，汤主把话题拨了回来。"}]},
  {"id":"o-busseat","title":"一直空着的座位","tag":"催泪系","cats":["温情","催泪","旅途"],"difficulty":1,"par":7,"original":true,"surface":"早班公交上，老人上车后，车厢里明明还有一个空位，却没有一个人去坐。老人坐下后，对着旁边的空位轻声说了一句：“到了。”为什么？","truth":"那个空位是老人的妻子生前每天坐的位置。他们一起坐这趟早班车坐了三十多年。妻子去世后，老人还是每天照旧上车、照旧报站名给她听。常坐这趟车的乘客都知道这件事，谁也不会去坐那个位置。","truthKeywords":["空位","座位","老人","妻子","去世","早班车","三十多年","报站","到了","乘客"],"coreKeywords":["空位","妻子","到了"],"hints":["那个位置，是有主人的。","他对旁边说的话，是每天都要说的一句。"],"clues":[{"kw":["空位","空着的座位","那个位置"],"type":"yes","text":"是。那个位置一直有人“坐着”。"},{"kw":["妻子","老伴","老婆"],"type":"yes","text":"是。那是他妻子的位置。"},{"kw":["去世","过世","不在了"],"type":"yes","text":"是。她已经不在了。"},{"kw":["早班车","这趟车","公交车"],"type":"yes","text":"是。他们一起坐这趟车，坐了很多年。"},{"kw":["到了","报站","说话"],"type":"yes","text":"是。那句“到了”，是他每天都要跟她说的一句。"},{"kw":["三十","很多年","几十年"],"type":"yes","text":"是。这趟车他们一起坐了三十多年。"},{"kw":["乘客","大家","没人坐"],"type":"yes","text":"是。同车的乘客都知道，所以没人去坐。"},{"kw":["不让坐","占座","霸位"],"type":"no","text":"不是。他不是在霸位，也没人不让他坐。"},{"kw":["腿脚不便","生病","让座"],"type":"irr","text":"与此无关。这跟让座和身体没关系。"}]},
  {"id":"o-twins","title":"一模一样的两张画","tag":"悬疑系","cats":["悬疑","推理","校园"],"difficulty":2,"par":8,"original":true,"surface":"美术课上，双胞胎姐妹交上来的作业一模一样，连画错的地方都分毫不差。老师把两人叫来，姐姐说“我画的”，妹妹也说“我画的”。老师翻过画纸背面，立刻联系了家长。为什么？","truth":"两张画的背面，写着同一个学号。那个学号属于一个去年因病去世的学生——她是姐妹俩最好的朋友。她生前没画完的那幅画，一直夹在美术教室的柜子里。姐妹俩谁都没有照抄对方，她们是各自照着同一张未完成的画，一笔一笔替她画完的。老师联系家长，是想把这两张画和那件事，好好跟孩子们谈一谈。","truthKeywords":["双胞胎","画","一模一样","学号","背面","去世","朋友","未完成","美术教室","家长"],"coreKeywords":["学号","背面","未完成"],"hints":["她们没有互相抄——她们照的是同一个东西。","两张画纸的背面，写着同样的字。","那个学号的主人，已经不在了。"],"clues":[{"kw":["双胞胎","姐妹","两个人"],"type":"yes","text":"是。交作业的是双胞胎姐妹。"},{"kw":["一模一样","画错的地方一样","分毫不差"],"type":"yes","text":"是。两张画连错的地方都一样。"},{"kw":["学号","背面","写在背面"],"type":"yes","text":"是。关键在画纸背面那串学号。"},{"kw":["去世","不在了","走了"],"type":"yes","text":"是。那个学号的主人已经去世了。"},{"kw":["朋友","同学","最好的朋友"],"type":"yes","text":"是。她是姐妹俩最好的朋友。"},{"kw":["未完成","没画完","画到一半"],"type":"yes","text":"是。她们照着同一张没画完的画往下画。"},{"kw":["美术教室","柜子","夹在"],"type":"yes","text":"是。那张画一直夹在美术教室的柜子里。"},{"kw":["家长","联系家长","老师"],"type":"yes","text":"是。老师看完背面，联系了家长。"},{"kw":["抄作业","照抄","作弊"],"type":"no","text":"不是。她们谁都没有抄谁。"},{"kw":["打印机","描摹","复制"],"type":"irr","text":"与此无关。没有打印机，也没有人描摹。"}]},
  {"id":"o-odometer","title":"没变过的里程表","tag":"推理系","cats":["推理","反转","都市"],"difficulty":3,"par":9,"original":true,"surface":"男人把车停在小区固定车位，出差半个月。回来时，他发现车的位置偏了半米，车身上多了几道细划痕，可里程表的数字和走之前一模一样。他报了警。为什么？","truth":"有人动过他的车。为了不留下里程证据，那人用千斤顶把车抬起来，换上自己的轮胎开出去，办完事再抬回原位、换回原轮胎——里程表自然一点没走。划痕是千斤顶的托盘蹭的。警方顺着这条线查，发现有人在用别人的车运不该运的东西。","truthKeywords":["里程表","没变","千斤顶","抬起来","轮胎","换胎","划痕","位置偏了","动过车","报警"],"coreKeywords":["里程表","千斤顶","动过车"],"hints":["车被开走了，可里程表不认。","有人能让他看不见“走过多少路”。","车身上那几道划痕，是工具留下的。","最后一条：把「里程表」和「千斤顶」连起来想想——它们之间差了什么？"],"clues":[{"kw":["里程表","公里数","数字没变"],"type":"yes","text":"是。里程表一动不动，正是破绽所在。"},{"kw":["千斤顶","顶起来","抬起来"],"type":"yes","text":"是。有人用千斤顶把车抬了起来。"},{"kw":["轮胎","换胎","轮子"],"type":"yes","text":"是。他换上自己的轮胎开出去，回来再换回来。"},{"kw":["划痕","刮痕","蹭的"],"type":"yes","text":"是。那几道划痕是工具托盘蹭出来的。"},{"kw":["位置偏了","挪过","动过车"],"type":"yes","text":"是。车被挪动过，只是又放回了原处。"},{"kw":["运东西","偷运","违法"],"type":"yes","text":"是。有人用他的车运了不该运的东西。"},{"kw":["出差","半个月","不在家"],"type":"yes","text":"是。他出差了半个月，这段时间车没人看。"},{"kw":["报警","警察"],"type":"yes","text":"是。他顺着这条线报了警。"},{"kw":["记错","看错","眼花"],"type":"no","text":"不是。他没有记错，数字确实一点没变。"},{"kw":["拖车","违章","停车费"],"type":"no","text":"不是。车没有被拖走，也不是违章停车。"},{"type":"irr","kw":["男人把车"],"text":"与此无关。「男人把车」不在这个故事里，换个方向问吧。"}]},
  {"id":"o-hair","title":"盒子里的头发","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":2,"par":8,"original":true,"surface":"女人每天梳完头，都会把掉下来的头发仔细收进一个铁盒里。儿子小时候笑她小气，长大后打开那个盒子，却蹲在地上哭了很久。为什么？","truth":"女人在确诊后开始化疗，知道自己的头发很快会掉光。她怕儿子以后记不得妈妈长发的样子，就把每一次梳头掉下的头发都收进铁盒，一天一天攒着。盒子底下压着一张纸条，写着：“妈妈的头发，留给你。”","truthKeywords":["头发","铁盒","盒子","收起来","化疗","掉光","儿子","纸条","长发","留给你"],"coreKeywords":["头发","化疗","盒子"],"hints":["她收的不是垃圾，是别的东西。","她知道自己的头发快要保不住了。","盒子底下还压着一张纸。"],"clues":[{"kw":["头发","掉下来的头发","梳头"],"type":"yes","text":"是。她收起来的是自己的头发。"},{"kw":["铁盒","盒子","收进盒里"],"type":"yes","text":"是。那些头发被仔细收在一个铁盒里。"},{"kw":["化疗","治疗","生病"],"type":"yes","text":"是。她当时正在做化疗。"},{"kw":["掉光","掉没了","保不住"],"type":"yes","text":"是。她知道自己的头发很快就会掉光。"},{"kw":["儿子","孩子"],"type":"yes","text":"是。她做这件事，是为了儿子。"},{"kw":["纸条","写字","留下一句话"],"type":"yes","text":"是。盒子底下压着一张纸条。"},{"kw":["长发","长头发的样子","记不得"],"type":"yes","text":"是。她怕儿子以后记不得妈妈长发的样子。"},{"kw":["攒着","一天一天","每天收"],"type":"yes","text":"是。这些头发是她一天一天攒起来的。"},{"kw":["卖钱","值钱","舍不得扔"],"type":"no","text":"不是。她不是为了卖钱，也不是小气。"},{"kw":["理发","剪头发","假发"],"type":"irr","text":"与此无关。这不是一次理发，也不是做假发。"}]},
  {"id":"o-chess","title":"只走一步的棋","tag":"推理系","cats":["悬疑","推理","反转"],"difficulty":3,"par":9,"original":true,"surface":"老人每天在公园和一个陌生男人下棋，三年只走同一步。这天他第一次换了走法。对面那人愣了一下，掀翻棋盘就跑了。为什么？","truth":"那个“陌生人”，是当年撞死他儿子的肇事逃逸司机。老人认出他后没有报警，而是每天约他下棋，只走同一步——那一步的意思是“我在等你自首”。三年过去，对方一次都没动过。这天老人换了走法，那是儿子生前教他的一个杀招，意思是“我不等了”。司机知道身份已经暴露，掀桌就跑，在车站被警察抓住。","truthKeywords":["棋","同一步","换走法","肇事逃逸","司机","儿子","撞死","自首","等了三年","跑","报警"],"coreKeywords":["同一步","肇事逃逸","自首"],"hints":["那一步棋不是下着玩的，是一句话。","他等这个人开口，等了三年。","换走法的意思，是“我不等了”。","最后一条：把「同一步」和「肇事逃逸」连起来想想——它们之间差了什么？"],"clues":[{"kw":["下棋","棋盘"],"type":"yes","text":"是。那盘棋本身就是他们之间的对话。"},{"kw":["同一步","只走一步","每次都一样"],"type":"yes","text":"是。三年里他每次都走同一步。"},{"kw":["肇事逃逸","撞死","车祸"],"type":"yes","text":"是。对方撞死了人，然后逃了。"},{"kw":["司机","开车","那个人"],"type":"yes","text":"是。那个“陌生人”，就是当年的司机。"},{"kw":["儿子","他的孩子","死者"],"type":"yes","text":"是。被撞死的是他的儿子。"},{"kw":["自首","认罪","等他开口"],"type":"yes","text":"是。他走那一步，是在等对方自首。"},{"kw":["换走法","改了","杀招"],"type":"yes","text":"是。他换的这一步，是儿子教他的杀招。"},{"kw":["掀桌"],"type":"yes","text":"是。对方掀了棋盘就跑，最后在车站被抓。"},{"kw":["输赢","赌钱","彩头"],"type":"no","text":"不是。他们下棋不赌钱，也不分输赢。"},{"kw":["棋友","老朋友","邻居"],"type":"no","text":"不是。他们不是棋友，也不是邻居。"},{"type":"irr","kw":["老人每天"],"text":"与此无关。汤主摇头：「老人每天」和汤底扯不上。"}]},
  {"id":"o-piano","title":"永远弹不完的曲子","tag":"悬疑系","cats":["温情","催泪","都市"],"difficulty":2,"par":8,"original":true,"surface":"女人每晚十点都会听见楼下弹同一首钢琴曲，每次都停在同一小节。这天晚上，那首曲子第一次弹完了。她听着听着，眼泪就下来了。为什么？","truth":"楼下住着一位患了阿尔茨海默症的老人。那首曲子是他当年写给妻子的，也是他唯一还记得的旋律。病后他的记忆每天都会断在同一个地方，女儿每晚陪他练，一遍一遍。这天晚上，他终于把整首曲子从头到尾弹完了——女儿在楼道里哭，楼上的女人也听懂了。","truthKeywords":["钢琴","同一首曲子","同一小节","弹完","老人","阿尔茨海默","妻子","女儿","记忆","每晚"],"coreKeywords":["同一小节","阿尔茨海默","弹完"],"hints":["停下来的地方，从来不是他累了。","那首曲子对楼下的人来说，有特殊的意义。","曲子终于完整的那天，意味着什么？"],"clues":[{"kw":["钢琴","弹琴","琴声"],"type":"yes","text":"是。楼下每晚都有人在弹琴。"},{"kw":["同一首曲子","同一小节","停在那里"],"type":"yes","text":"是。他每次都停在同一小节。"},{"kw":["弹完","弹完了","完整"],"type":"yes","text":"是。这天晚上，曲子第一次完整地弹完了。"},{"kw":["老人","楼下的住户"],"type":"yes","text":"是。弹琴的是一位老人。"},{"kw":["阿尔茨海默","老年痴呆","记不住"],"type":"yes","text":"是。他的记忆出了问题，每天都会断在同一处。"},{"kw":["妻子","老伴","写给她的"],"type":"yes","text":"是。那首曲子是他写给妻子的。"},{"kw":["女儿","陪他练","家人"],"type":"yes","text":"是。每晚陪他练琴的，是他的女儿。"},{"kw":["记忆","想起来","记得"],"type":"yes","text":"是。弹完的那一晚，他找回了完整的记忆。"},{"kw":["琴坏了","走音","学不会"],"type":"no","text":"不是。琴没有坏，他也不是不会弹。"},{"kw":["噪音","投诉","太吵"],"type":"irr","text":"与此无关。楼上的人从来没想过投诉。"}]},
  {"id":"o-grave","title":"墓前的新花","tag":"悬疑系","cats":["悬疑","推理","旅途"],"difficulty":3,"par":9,"original":true,"surface":"男人每年清明都去给一个和他没有血缘关系的人扫墓。今年他扫到一半，看见墓前摆着一束还带着露水的新花，立刻报了警。为什么？","truth":"墓里埋的是他妹妹。二十年前，妹妹被人贩子带走，再也没回来，后来警方在异地找到了她的遗骨。男人一直恨自己：当年是他把妹妹交给那个“说带她去买糖”的人的。这束带露水的新花说明，摆花的人今天刚来过——而知道这座墓位置的人，除了他和警方，只有当年那个人贩子。警方在墓园外抓到了人。","truthKeywords":["墓","扫墓","新花","露水","妹妹","人贩子","带走","遗骨","报警","墓园","警方","二十年"],"coreKeywords":["新花","妹妹","人贩子"],"hints":["那束花是今天早上才放的。","知道这座墓在哪的人，本来就不多。","他一直恨的，是自己。","最后一条：把「新花」和「妹妹」连起来想想——它们之间差了什么？"],"clues":[{"kw":["扫墓"],"type":"yes","text":"是。他每年都来扫这座墓。"},{"kw":["新花","花束","露水"],"type":"yes","text":"是。那束花今天早上才被人放下。"},{"kw":["妹妹","亲人"],"type":"yes","text":"是。墓里埋的是他的妹妹。"},{"kw":["人贩子","拐走","带走"],"type":"yes","text":"是。当年带走妹妹的，是一个人贩子。"},{"kw":["遗骨","找到","尸体"],"type":"yes","text":"是。妹妹的遗骨是后来在异地被找到的。"},{"kw":["报警","警察"],"type":"yes","text":"是。他立刻报了警，警方在墓园外抓到了人。"},{"kw":["二十年","二十年前","很多年"],"type":"yes","text":"是。这件事已经过去二十年了。"},{"kw":["内疚","恨自己","怪自己"],"type":"yes","text":"是。他一直恨的是自己。"},{"kw":["亲戚","家人","朋友"],"type":"no","text":"不是。他和墓里的人没有血缘，也不是朋友。"},{"kw":["花店","送错","上错坟"],"type":"no","text":"不是。花不是花店送错的，也没有上错坟。"},{"type":"irr","kw":["男人每年"],"text":"与此无关。这一锅和「男人每年」没有关系，汤主把话题拨了回来。"}]},
  {"id":"o-tide","title":"退潮后的脚印","tag":"推理系","cats":["推理","悬疑","旅途"],"difficulty":3,"par":9,"original":true,"surface":"退潮后，沙滩上出现一串赤脚印，从海里一直走到沙滩中央，然后就没有了——没有回去的脚印，也没有别的痕迹。男人看了一眼就报了警。为什么？","truth":"脚印的方向是从海走向岸。有人想让警方以为死者是自己下海游泳溺亡的，就把尸体搬到海里再放回去——可尸体被拖动时，脚是朝着岸边的，于是留下了一串“从海里走出来”的脚印。真正的事实是：死者先被人从背后推下防波堤，落水前已经在岸上。警方顺着脚印反查，找到了凶手。","truthKeywords":["脚印","退潮","赤脚","从海里","方向","伪造","溺亡","尸体","拖动","凶手","防波堤","报警"],"coreKeywords":["脚印","方向","伪造"],"hints":["脚印的朝向，和凶手想说的故事是反的。","死人不会走路，可脚印是真的。","他想让大家相信，这个人是自己走进海里的。","最后一条：把「脚印」和「方向」连起来想想——它们之间差了什么？"],"clues":[{"kw":["脚印","赤脚印","沙上"],"type":"yes","text":"是。那串脚印是真的，方向却不对。"},{"kw":["方向","从海里走出来","朝岸"],"type":"yes","text":"是。脚印是从海走向岸的。"},{"kw":["退潮","潮水","海边"],"type":"yes","text":"是。脚印是退潮后才露出来的。"},{"kw":["伪造","伪装","假的现场"],"type":"yes","text":"是。现场是被人摆出来的。"},{"kw":["溺亡","淹死","自杀"],"type":"yes","text":"是。有人想让警方以为他是自己溺亡的。"},{"kw":["拖动"],"type":"yes","text":"是。尸体被拖动时，脚朝着岸边，才留下了这串脚印。"},{"kw":["凶手","推下去","防波堤"],"type":"yes","text":"是。他是被人从防波堤上推下去的。"},{"kw":["报警","警察"],"type":"yes","text":"是。男人看了一眼就报了警。"},{"kw":["涨潮","浪太大","游泳"],"type":"no","text":"不是。他不是来游泳的，也不是被浪卷走的。"},{"kw":["鞋印","自行车","轮胎"],"type":"no","text":"不是。现场没有鞋印，也没有车辙。"},{"type":"irr","kw":["潮后沙滩"],"text":"与此无关。「潮后沙滩」不在这个故事里，换个方向问吧。"}]},
  {"id":"o-copykey","title":"能开邻居门的钥匙","tag":"推理系","cats":["推理","反转","家庭"],"difficulty":2,"par":8,"original":true,"surface":"男人无意中发现，自己家的钥匙居然能打开隔壁邻居的门。他没有进去，也没有告诉邻居，而是先跑了一趟五金店，回来后才敲开邻居的门。为什么？","truth":"这栋楼是同一批开发商建的，整层用的锁芯都是同一型号，钥匙可以互开。男人去五金店配了一大串同款钥匙，然后挨家挨户敲门，当场演示给他们看，劝大家赶紧换锁。因为如果他能打开邻居的门，说明别人也能打开他家的门。","truthKeywords":["钥匙","邻居","门","同一型号","锁芯","开发商","五金店","配钥匙","换锁","挨家挨户"],"coreKeywords":["钥匙","同一型号","换锁"],"hints":["他不是想进去，是想告诉大家一件事。","出问题的不是邻居的门，是整层楼的锁。","他能开别人家的门，说明别人也能开他家的。"],"clues":[{"kw":["钥匙","我家的钥匙","自己的钥匙"],"type":"yes","text":"是。他家的钥匙，能开邻居家的门。"},{"kw":["邻居","隔壁","对门"],"type":"yes","text":"是。被打开的是邻居家的门。"},{"kw":["同一型号","同款","一批"],"type":"yes","text":"是。整层楼的锁芯都是同一型号。"},{"kw":["五金店","配钥匙","配锁"],"type":"yes","text":"是。他先跑了一趟五金店，配了一串同款钥匙。"},{"kw":["换锁","赶紧换","提醒"],"type":"yes","text":"是。他挨家挨户敲门，劝大家赶紧换锁。"},{"kw":["演示","当场开","试给他们看"],"type":"yes","text":"是。他当着邻居的面，把门打开了。"},{"kw":["开发商","建筑商","装锁的人"],"type":"yes","text":"是。问题出在当年装锁的人身上。"},{"kw":["危险","别人也能开","不安全"],"type":"yes","text":"是。他能开邻居的门，说明别人也能开他家的门。"},{"kw":["偷东西","入室","盗窃"],"type":"no","text":"不是。他没进去过，也不是为了偷东西。"},{"kw":["钥匙丢了","换过锁","房东"],"type":"no","text":"不是。他既没丢钥匙，也没换过锁。"},{"type":"irr","kw":["男人无意"],"text":"与此无关。汤主摇头：「男人无意」和汤底扯不上。"}]},
  {"id":"o-seatbelt","title":"副驾上的安全带","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":1,"par":7,"original":true,"surface":"女人一个人开车，副驾却永远系着安全带。同事笑她多此一举，她只是笑笑。只有一次，她忘了系，开出两条街后停在路边哭了很久。为什么？","truth":"她的丈夫在几年前的一场车祸里走了，那天他坐在副驾，没有系安全带。从那以后，她每天上车第一件事，就是把副驾的安全带扣上——像是替他把安全带系好。那天她忘了，开出两条街才想起来，那一瞬间她忽然觉得，自己又把他弄丢了一次。","truthKeywords":["副驾","安全带","系上","丈夫","车祸","走了","没系","每天","忘了","哭"],"coreKeywords":["安全带","副驾","丈夫"],"hints":["那条安全带不是给她自己系的。","副驾上曾经坐着一个人。"],"clues":[{"kw":["安全带","系安全带","扣上"],"type":"yes","text":"是。关键就是那条安全带。"},{"kw":["副驾","副驾驶","旁边的位置"],"type":"yes","text":"是。她系的是副驾的安全带。"},{"kw":["丈夫","老公"],"type":"yes","text":"是。那个位置原来坐的是她丈夫。"},{"kw":["车祸","事故","出事"],"type":"yes","text":"是。他在一场车祸里走了。"},{"kw":["没系","没系安全带","疏忽"],"type":"yes","text":"是。那天他没有系安全带。"},{"kw":["每天","每次都系","习惯"],"type":"yes","text":"是。她每天都替他把安全带系上。"},{"kw":["忘了","忘记","没想起来"],"type":"yes","text":"是。她唯一一次忘了，是在开出两条街之后。"},{"kw":["停在路边","难受"],"type":"yes","text":"是。她停在路边哭了很久。"},{"kw":["怕死","胆小","谨慎"],"type":"no","text":"不是。她不是胆小，也不是怕自己出事。"},{"kw":["同事","顺路带人","载客"],"type":"no","text":"不是。副驾从不载人，她也不是怕别人出事。"},{"type":"irr","kw":["女人一个"],"text":"与此无关。这一锅和「女人一个」没有关系，汤主把话题拨了回来。"}]},
  {"id":"o-stationwave","title":"站台上挥手的老人","tag":"催泪系","cats":["温情","催泪","旅途"],"difficulty":2,"par":8,"original":true,"surface":"女孩每周五坐火车经过一个小站，总能看见站台上有个老人朝她挥手。她特意下车去找，却怎么也找不到人。回到家，她哭了。为什么？","truth":"那位老人是她的养父。她长大后去了外地工作，老人怕打扰她，从不上前相认，只是算准了她回家的车次，每周五下午到站台上站一会儿。女孩下车找不到他，是因为那天老人被家人送进了医院——他患了阿尔茨海默症，记不清日子，只记得“女儿的车会从这里经过”。","truthKeywords":["站台","挥手","老人","养父","火车","每周五","车次","医院","阿尔茨海默","记不清"],"coreKeywords":["站台","养父","阿尔茨海默"],"hints":["那位老人认识她，她却不认识他。","他每次都算准时间，从不走近。","他记不清日子，却记得一件事。"],"clues":[{"kw":["站台","小站","月台"],"type":"yes","text":"是。那个站台是他固定出现的地方。"},{"kw":["挥手","打招呼","朝她挥手"],"type":"yes","text":"是。他每次都只是朝她挥手，从不上前。"},{"kw":["老人","那位老人"],"type":"yes","text":"是。那位老人是认识她的。"},{"kw":["养父","收养","养大"],"type":"yes","text":"是。老人是把她养大的人。"},{"kw":["每周五","车次","算准"],"type":"yes","text":"是。他算准了她每周五的车次。"},{"kw":["医院","住院","送医"],"type":"yes","text":"是。那天他被家人送进了医院。"},{"kw":["阿尔茨海默","老年痴呆","记不清"],"type":"yes","text":"是。他记不清日子，只记得女儿的车会经过。"},{"kw":["打扰","不上前","远远看着"],"type":"yes","text":"是。他怕打扰她，所以只远远地站着。"},{"kw":["陌生人","路人","认错人"],"type":"no","text":"不是。他不是陌生人，也没有认错人。"},{"kw":["列车员","同事","朋友"],"type":"irr","text":"与此无关。他跟铁路上的工作没有关系。"}]},
  {"id":"o-giftbox","title":"十年没拆的礼物","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":2,"par":8,"original":true,"surface":"男人每年生日都会收到一个没有署名的礼物，他从来不拆，只是收进柜子。十年后的这个生日，他第一次拆开了其中一个，然后哭了很久。为什么？","truth":"这些礼物是他母亲留下的。母亲病重时知道自己等不到儿子长大，就提前准备了十年的生日礼物，托邻居每年生日那天送到他门口。男人一直不敢拆——因为只要不拆，就意味着“柜子里还有下一个”，母亲就还在给他过生日。第十年，他拆开了。","truthKeywords":["礼物","生日","没署名","不拆","母亲","病重","提前准备","十年","邻居","柜子"],"coreKeywords":["礼物","母亲","十年"],"hints":["他不拆，不是因为不想要。","这些礼物是提前很久就准备好的。","不拆，就意味着还有下一个。"],"clues":[{"kw":["礼物","盒子","包裹"],"type":"yes","text":"是。他每年收到的都是一个没署名的礼物。"},{"kw":["生日","每年生日","过生日"],"type":"yes","text":"是。礼物只在生日那天出现。"},{"kw":["母亲","妈妈"],"type":"yes","text":"是。准备这些礼物的人是他的母亲。"},{"kw":["病重","生病","知道自己等不到"],"type":"yes","text":"是。她病重时就知道，自己等不到儿子长大。"},{"kw":["提前准备","准备好","十年份"],"type":"yes","text":"是。她提前准备了十年的生日礼物。"},{"kw":["邻居","托付","送来"],"type":"yes","text":"是。礼物是托邻居每年送来的。"},{"kw":["不拆","没拆","收进柜子"],"type":"yes","text":"是。他一直不敢拆，只把它们收进柜子。"},{"kw":["十年","第十年","今年"],"type":"yes","text":"是。第十年，他终于拆开了一个。"},{"kw":["讨厌","生气","不想收"],"type":"no","text":"不是。他不是讨厌这些礼物。"},{"kw":["匿名","粉丝","追求者"],"type":"no","text":"不是。这不是谁在暗恋他，也不是恶作剧。"},{"type":"irr","kw":["男人每年"],"text":"与此无关。「男人每年」不在这个故事里，换个方向问吧。"}]},
  {"id":"o-window4","title":"四号窗口","tag":"悬疑系","cats":["温情","悬疑","都市"],"difficulty":2,"par":8,"original":true,"surface":"老人每天上午都来银行坐一会儿，从不办业务，只看着四号窗口。柜员换了一茬又一茬。这天，新来的柜员多问了他一句，老人当场哭了。为什么？","truth":"四号窗口曾经是他女儿工作的地方。多年前的一次抢劫中，她为了护住客户挡在了前面，没能活下来。老人每天来看这个窗口，是想看看现在坐在那里的人过得好不好——有没有被为难，有没有被欺负。新柜员问他的那句是：“您是不是在等人？”他这才哭出来。","truthKeywords":["窗口","四号窗口","银行","女儿","抢劫","护住","客户","柜员","每天来","等"],"coreKeywords":["四号窗口","女儿","抢劫"],"hints":["他看的不是窗口，是窗口后面的那个人。","那个位置曾经属于他的家人。","新柜员问的那句话，正好问到了点上。"],"clues":[{"kw":["窗口","四号窗口","柜台"],"type":"yes","text":"是。他一直盯着四号窗口看。"},{"kw":["银行","来坐一会儿","不办业务"],"type":"yes","text":"是。他每天来银行，却从不办业务。"},{"kw":["女儿","他女儿","孩子"],"type":"yes","text":"是。那个位置原来坐的是他女儿。"},{"kw":["抢劫","歹徒","出事"],"type":"yes","text":"是。多年前这里发生过一次抢劫。"},{"kw":["护住","挡在前面","救人"],"type":"yes","text":"是。她挡在了客户前面。"},{"kw":["柜员","新来的","工作人员"],"type":"yes","text":"是。新柜员多问了他一句。"},{"kw":["每天来","每天都来","看一会儿"],"type":"yes","text":"是。他每天都来看一会儿。"},{"kw":["等人","在等人","问的那句"],"type":"yes","text":"是。新柜员问的正是“您是不是在等人”。"},{"kw":["取钱","存钱","理财"],"type":"no","text":"不是。他不是来取钱或办业务的。"},{"kw":["排队","投诉","服务态度"],"type":"irr","text":"与此无关。这跟排队和投诉没有关系。"}]},
  {"id":"o-sandbox","title":"装满沙子的行李箱","tag":"推理系","cats":["推理","悬疑","旅途"],"difficulty":2,"par":8,"original":true,"surface":"海关拦下一个行李箱，打开一看，整箱都是沙子。旅客说这是从海边带回来的纪念品。关员把箱子抬起来掂了掂，立刻把人扣下了。为什么？","truth":"沙子是真的，但箱子里有夹层。有人把走私品封在箱体中间，再灌满沙子——这样过 X 光时，整箱看起来就只是“一箱沙子”。可沙子是均匀的，重量却分布不均：关员掂的时候，明显感觉到中间有硬块。撬开箱壁，里面是藏好的走私品。","truthKeywords":["沙子","行李箱","夹层","重量","硬块","走私","X光","纪念品","关员","扣下"],"coreKeywords":["沙子","夹层","走私"],"hints":["沙子没有问题，问题是沙子底下。","他掂的不是重量，是重量的分布。","过安检时，整箱沙子看起来最“干净”。"],"clues":[{"kw":["沙子","整箱沙子","装沙"],"type":"yes","text":"是。沙子本身没有问题——有问题的是别的地方。"},{"kw":["夹层","箱壁","中间"],"type":"yes","text":"是。箱体中间有一层夹层。"},{"kw":["重量","掂了掂","分布不均"],"type":"yes","text":"是。沙子是均匀的，重量却不是。"},{"kw":["硬块","中间有东西","硬的"],"type":"yes","text":"是。关员明显感觉到中间有硬块。"},{"kw":["走私","违禁品","藏东西"],"type":"yes","text":"是。夹层里藏着走私品。"},{"kw":["X光","安检","扫描"],"type":"yes","text":"是。灌沙子是为了骗过 X 光。"},{"kw":["纪念品","海边带回来","借口"],"type":"yes","text":"是。“海边纪念品”只是一个借口。"},{"kw":["扣下","扣人","拦下"],"type":"yes","text":"是。关员当场把人扣下了。"},{"kw":["超重","托运","罚款"],"type":"no","text":"不是。扣人不是因为超重或罚款。"},{"kw":["沙子有毒","放射性","危险品"],"type":"no","text":"不是。沙子本身没有毒，也不危险。"},{"type":"irr","kw":["下一个行"],"text":"与此无关。汤主摇头：「下一个行」和汤底扯不上。"}]},
  {"id":"o-lullaby","title":"只唱一半的摇篮曲","tag":"催泪系","cats":["温情","催泪","家庭"],"difficulty":2,"par":8,"original":true,"surface":"女人每晚给女儿唱摇篮曲，每次都只唱到一半就停下。女儿长大后问她为什么，她说：“后面那半句，我记不得了。”多年后，女儿把整首歌放给她听，她哭了。为什么？","truth":"女人小时候在孤儿院长大，只记得母亲哼过的前半段旋律，后半段怎么也记不起来。她一直唱到那里就停，是怕自己瞎编的调子，会把真正的记忆盖掉。多年后，女儿在网上找到了那首老曲子，把完整的一遍放给她听——那是她母亲的声音之外，她第一次听见完整的家。","truthKeywords":["摇篮曲","一半","停下","记不得","孤儿院","母亲","旋律","完整","女儿","找到"],"coreKeywords":["摇篮曲","一半","孤儿院"],"hints":["她停下来，不是因为困了。","那首歌的前半段，是从一个很远的地方带来的。","她怕自己编的调子，会盖住真正的记忆。"],"clues":[{"kw":["摇篮曲","那首歌","唱歌"],"type":"yes","text":"是。那首摇篮曲是她每晚都要唱的。"},{"kw":["一半","唱到一半","停下"],"type":"yes","text":"是。她每次都只唱到一半就停。"},{"kw":["记不得","忘了","想不起来"],"type":"yes","text":"是。后半段她确实记不起来了。"},{"kw":["孤儿院","孤儿","院长"],"type":"yes","text":"是。她小时候在孤儿院长大。"},{"kw":["母亲","她妈妈","亲妈"],"type":"yes","text":"是。前半段旋律是她母亲哼给她听的。"},{"kw":["旋律","调子","曲子"],"type":"yes","text":"是。她只记得前半段的旋律。"},{"kw":["完整","整首","放给她听"],"type":"yes","text":"是。女儿找到了完整的那首曲子。"},{"kw":["女儿","孩子"],"type":"yes","text":"是。找到曲子的是她的女儿。"},{"kw":["嗓子","声音哑","唱不上去"],"type":"no","text":"不是。她不是嗓子不好，也不是唱不上去。"},{"kw":["催眠","哄睡","怕吵"],"type":"no","text":"不是。停下来不是因为孩子睡着了。"},{"type":"irr","kw":["女人每晚"],"text":"与此无关。这一锅和「女人每晚」没有关系，汤主把话题拨了回来。"}]},
  {"id":"o-locker","title":"储物柜里的东西","tag":"推理系","cats":["推理","悬疑","职场"],"difficulty":3,"par":9,"original":true,"surface":"女人每天在健身房用同一个储物柜。这天她打开柜子，发现里面多了一个不属于她的东西。她没有碰，直接报了警。为什么？","truth":"健身房那批储物柜的锁是通用锁，一把钥匙能打开好几个柜子。有人专门利用这一点转移赃物：先把东西放进别人的柜子，等风声过了再取。女人一眼就认出，里面是一只和她上个月失窃时一模一样的首饰盒。她没有伸手，而是锁好柜门直接报警——因为如果有人知道她的柜号，那个人也可能正在看着她。","truthKeywords":["储物柜","柜子","钥匙","通用锁","赃物","首饰盒","失窃","转移","报警","柜号"],"coreKeywords":["储物柜","通用锁","赃物"],"hints":["那个柜子本来不该有别人的东西。","钥匙能开的，不止她这一个柜子。","她没有碰它，因为她认得那是什么。","最后一条：把「储物柜」和「通用锁」连起来想想——它们之间差了什么？"],"clues":[{"kw":["储物柜","柜子","更衣柜"],"type":"yes","text":"是。秘密就在健身房的储物柜上。"},{"kw":["钥匙","通用锁","一把钥匙开几个"],"type":"yes","text":"是。那批锁是通用锁，一把钥匙能开好几个柜子。"},{"kw":["赃物","偷来的","不属于她"],"type":"yes","text":"是。柜子里的东西是赃物。"},{"kw":["首饰盒","盒子","认出来"],"type":"yes","text":"是。她一眼就认出了那个首饰盒。"},{"kw":["失窃","丢过","被偷"],"type":"yes","text":"是。她上个月也丢过一样的东西。"},{"kw":["转移","放进别人柜子","等风声"],"type":"yes","text":"是。有人专门用别人的柜子转移赃物。"},{"kw":["报警","警察","没碰"],"type":"yes","text":"是。她没有碰，直接锁好柜门报了警。"},{"kw":["柜号","知道她的柜子","被盯着"],"type":"yes","text":"是。知道她柜号的人，可能也在盯着她。"},{"kw":["自己放错","记错柜子","忘记"],"type":"no","text":"不是。她没放错，也不是记错了柜子。"},{"kw":["健身教练","会员","前台"],"type":"no","text":"不是。东西不是教练或前台放的。"},{"type":"irr","kw":["女人每天"],"text":"与此无关。「女人每天」不在这个故事里，换个方向问吧。"}]}
];

